window.EXTRA_DATA_2 = [{"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 1, "en": "Annie loves Hector and Hector loves Annie.", "zh": "安妮深爱着赫克托，赫克托也深爱着安妮。", "note": "恩爱情感 loves", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 2, "en": "Bridget and Nick are going out most of the time.", "zh": "布里吉特和尼克大部分时间都在甜蜜约会。", "note": "稳定交往 going out", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 3, "en": "I forgot. I won't make a sound.", "zh": "我给忘了，我保证不再发出一点声音。", "note": "保持安静 make a sound", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 4, "en": "What is a makeover? — It's when you use make-up to turn this into this!", "zh": "什么是大改造？— 就是用化妆把素颜变成这样！", "note": "时尚大改造 makeover", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 5, "en": "Bridget, you look like a film star!", "zh": "布里吉特，你现在看起来简直就像个电影巨星！", "note": "夸赞美貌 film star", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 6, "en": "Cameron Diaz, watch out!", "zh": "卡梅隆·迪亚兹，你可得小心提防被比下去了！", "note": "自信调侃 watch out", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 7, "en": "Nick wants to be a Hollywood movie star.", "zh": "尼克一心渴望成为好莱坞电影巨星。", "note": "演艺梦想 movie star", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 8, "en": "If he can do it, I can do it.", "zh": "如果他都能办得到，那我也绝对没问题。", "note": "自信宣言 I can do it", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 9, "en": "You are going to tell George Dukas about me?", "zh": "你真的打算向乔治·杜卡斯推荐引荐我吗？", "note": "引荐机会 tell about me", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 10, "en": "What? The Hollywood director?", "zh": "什么？那位好莱坞超级大导演？", "note": "难以置信 Hollywood director", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 11, "en": "You're going to tell him what a great actor I am!", "zh": "你要去告诉他我是一个多么优秀的演员！", "note": "自信吹嘘 great actor", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 12, "en": "Thank you so much. How can I thank you?", "zh": "真是太感谢你了，我该怎么好好答谢你呢？", "note": "表达感激 How can I thank you", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 13, "en": "Can't anyone else do it?", "zh": "难道就不能找别人来做这事吗？", "note": "无奈询问 anyone else", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 14, "en": "Of course I want you to tell George about me. No problem. See you later.", "zh": "我当然巴不得你在乔治面前多美言我几句，没问题，回头见！", "note": "答应条件 No problem", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 15, "en": "She's going to tell George Dukas the Hollywood director all about you.", "zh": "她打算把你的全部才华都引荐给好莱坞大导乔治·杜卡斯。", "note": "转告喜讯 all about you", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 16, "en": "Yeah, how did you know? — Lucky guess.", "zh": "对啊，你怎么会知道的？— 瞎猜碰巧蒙对的。", "note": "机智回答 Lucky guess", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 17, "en": "And what do you have to do for her? — Nothing.", "zh": "那你得替她办什么交换条件？— 没啥事。", "note": "心虚掩饰 Nothing", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 18, "en": "She wants me to look after something for her.", "zh": "她只不过是想让我帮她照看一件东西而已。", "note": "托付照看 look after", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 19, "en": "No problem, no problem at all.", "zh": "小事一桩，包在我身上完全没问题。", "note": "拍胸脯保证 at all", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 20, "en": "Okay, three rules: clean underpants in the morning, and in bed by eight.", "zh": "听好了，三条规矩：早上换干净内裤，晚上八点必须上床睡觉。", "note": "定下规矩 three rules", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 21, "en": "Say hello to Uncle Nick!", "zh": "快跟尼克舅舅打个招呼！", "note": "长辈称呼 Uncle Nick", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 22, "en": "George is waiting for me. Don't worry, Nick.", "zh": "乔治还在等着我呢。放宽心吧尼克。", "note": "赶赴约会 Don't worry", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 23, "en": "I'm going to tell him all about you.", "zh": "我一定会把你身上所有的亮点都告诉他的。", "note": "许下诺言 tell all about you", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 24, "en": "Be a good boy for Uncle Nick.", "zh": "要乖乖听尼克舅舅的话，当个好孩子。", "note": "叮嘱听话 be a good boy", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 25, "en": "Nick, what is going on?", "zh": "尼克，这到底是怎么一回事？", "note": "质问现状 what is going on", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 26, "en": "So she's got no one to look after Lucas.", "zh": "所以她找不到其他人能照看卢卡斯了。", "note": "说明原由 look after", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 27, "en": "So why can't she look after her own son?", "zh": "那她为什么不能自己照看亲生儿子呢？", "note": "犀利质问 own son", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 28, "en": "He won't be a problem. You won't even notice him.", "zh": "他绝不会惹麻烦的，你们甚至都感觉不到他的存在。", "note": "安抚室友 won't even notice", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 29, "en": "Well, you'd better not!", "zh": "哼，那最好真如你所说！", "note": "警告回怼 better not", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 30, "en": "My exams are next week, and I'm trying to revise.", "zh": "我下周就要期末考试了，我正拼命想要复习备考呢。", "note": "备考焦虑 trying to revise", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 31, "en": "There is a seven-year-old boy staying with us! It's all Nick's fault.", "zh": "居然有个七岁大的小男孩住进我们家！全都是尼克惹的祸。", "note": "怨气吐槽 all Nick's fault", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 32, "en": "I think there's trouble ahead.", "zh": "我看接下来肯定会有大麻烦找上门了。", "note": "预感不妙 trouble ahead", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 33, "en": "What's that noise? — Lucas is playing ball.", "zh": "那是什么古怪声响？— 卢卡斯在屋里玩皮球呢。", "note": "家里喧闹 playing ball", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 34, "en": "Don't go in the bathroom!", "zh": "千万别进卫生间！", "note": "灾难警告 bathroom", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 35, "en": "You must take control of him! — I'm trying!", "zh": "你必须管管他、控制住场面！— 我正在尽力啊！", "note": "焦头烂额 take control", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 36, "en": "Okay, let's play games.", "zh": "好吧，那我们来一起做游戏吧。", "note": "转移注意力 play games", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 37, "en": "Lucas, what have you done?", "zh": "卢卡斯，你到底干了什么好事？", "note": "抓狂质问 what have you done", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 38, "en": "The bad news is, her seven-year-old son Lucas is staying with us.", "zh": "坏消息是，她七岁大的儿子卢卡斯现在暂住在我们这儿。", "note": "坏消息 bad news", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 39, "en": "He's cute, but he's always hungry.", "zh": "他虽然蛮可爱的，但肚子总是在喊饿。", "note": "童真食量 always hungry", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 40, "en": "He likes playing tricks, too.", "zh": "而且他骨子里特别喜欢搞恶作剧捉弄人。", "note": "顽皮淘气 playing tricks", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 41, "en": "I knew Lucas would be trouble!", "zh": "我就知道让卢卡斯来准是一场大麻烦！", "note": "意料之中 would be trouble", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 42, "en": "My bathroom is a mess!", "zh": "我的卫生间被他搞得一团糟！", "note": "凌乱抓狂 is a mess", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 43, "en": "What are you listening to? Can I listen?", "zh": "你在听什么歌呢？我也能戴耳机听听吗？", "note": "好奇互动 Can I listen", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 44, "en": "Nick, thank you for a lovely day. — Well, that's okay, little fellow.", "zh": "尼克，谢谢你陪我度过这么美好的一天。— 没关系，小家伙。", "note": "温馨瞬间 little fellow", "b64": "", "src": "extra"}, {"l": 116, "lt": "Extra E16 尼克当舅舅", "i": 45, "en": "I'm going to be Mrs. George Dukas!", "zh": "我就要成为乔治·杜卡斯太太啦！", "note": "晴天霹雳 Mrs. George Dukas", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 1, "en": "Bridget and Nick were dating, but that's history.", "zh": "布里吉特和尼克以前约会过，但那都已成历史了。", "note": "恋情翻篇 that's history", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 2, "en": "Now all Nick wants is a job, a babe, or a motorbike. He's not fussy.", "zh": "现在尼克只要有工作、美女或摩托车就行，他不挑食。", "note": "不挑剔 not fussy", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 3, "en": "I'm going to buy a new computer for work. I need your help.", "zh": "我打算买一台新电脑办公，我需要你们帮忙参谋。", "note": "寻求协助 need your help", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 4, "en": "I know everything about computers.", "zh": "我可懂电脑了，所有电脑知识我都了如指掌。", "note": "打肿脸充胖子 know everything", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 5, "en": "I need one with a lot of gigabytes, good RAM, and top processor.", "zh": "我需要一台大硬盘、高运存、并且搭载顶级处理器的电脑。", "note": "电脑硬件参数 processor", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 6, "en": "No, this one hasn't got what she wants.", "zh": "不行，这台根本满足不了她的配置需求。", "note": "否定选项 what she wants", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 7, "en": "Who's going to pay for it? — It's for work, so they'll pay for it.", "zh": "这钱由谁来出？— 这是工作用的，单位给报销报销。", "note": "公费报销 they'll pay for it", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 8, "en": "This one is the most expensive. It's a nice colour.", "zh": "这台是最贵的，而且外观颜色特别好看。", "note": "选机偏好 most expensive", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 9, "en": "Well, it has everything you want.", "zh": "好吧，它确实具备了你想要的一切配置。", "note": "配置全面 everything you want", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 10, "en": "Waiting for my examination results.", "zh": "我在等候我的期末考试成绩单寄过来呢。", "note": "焦急等待 examination results", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 11, "en": "It says we are too noisy! — We're never noisy!", "zh": "上面说我们动静太吵了！— 我们哪有吵过，绝不可能！", "note": "邻里投诉 too noisy", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 12, "en": "You'd better have finished when I get back. — Better have finished what?", "zh": "等我回来时你最好已经全部搞定了。— 最好搞定什么？", "note": "命令下达 You'd better", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 13, "en": "Installing the computer. You do know everything about computers, don't you?", "zh": "安装配置好电脑啊。你不是自称什么都懂吗，难道不是吗？", "note": "反将一军 Installing", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 14, "en": "Oh, these instructions are all in English.", "zh": "噢天哪，这本说明书全都是英文写的。", "note": "说明书 instructions", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 15, "en": "Look, Hector, here's a Spanish version.", "zh": "快看，赫克托，这里有西班牙语版本的说明书。", "note": "多语种 Spanish version", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 16, "en": "I could do it with my eyes closed.", "zh": "我闭着眼睛都能把这玩意儿组装好。", "note": "极其自负 eyes closed", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 17, "en": "Instructions are for girls. I'm the man!", "zh": "说明书那是给女孩子看的，我可是真正的纯爷们！", "note": "迷之自信 I'm the man", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 18, "en": "Yeah, but I did all the work. I did it!", "zh": "拜托，活儿全都是我干的，是我搞定的！", "note": "争抢功劳 did all the work", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 19, "en": "I am the computer king!", "zh": "我才是真正的‘电脑之王’！", "note": "搞笑自封 computer king", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 20, "en": "You think you can beat me? — I already did.", "zh": "你以为你能赢得了我？— 我早就把你踩在脚下了。", "note": "较劲争胜 beat me", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 21, "en": "Computers are easy. How about a real challenge?", "zh": "装电脑太小儿科了。敢不敢来一场真正的终极对决？", "note": "发起挑战 real challenge", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 22, "en": "Whatever challenge you like. Man Olympics!", "zh": "随便你比什么我都奉陪。真汉子奥林匹克！", "note": "荒诞对决 Man Olympics", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 23, "en": "Who can put the most marshmallows in his mouth?", "zh": "谁能把最多的棉花糖一口塞进嘴里？", "note": "搞笑挑战 marshmallows", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 24, "en": "Soon I'll be emailing you on my new computer.", "zh": "很快我就能用我的新电脑给你发电子邮件啦。", "note": "日常愿望 emailing you", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 25, "en": "If I don't know my examination results soon, I will go crazy!", "zh": "如果不能尽快知道我的考试成绩，我整个人都要抓狂疯掉了！", "note": "抓狂心境 go crazy", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 26, "en": "Ten marshmallows I stuffed in my mouth. Two more than Hector!", "zh": "我嘴里整整塞了10颗棉花糖，比赫克托多出整整两颗！", "note": "幼稚炫耀 stuffed in mouth", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 27, "en": "By the way, do you know anything about computers?", "zh": "顺便问一句，你到底懂不懂电脑这方面的知识啊？", "note": "试探发问 know anything", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 28, "en": "I've got all the letters delivered to this building.", "zh": "我把送进整栋楼的所有信件全给搜罗过来了。", "note": "找信截胡 letters delivered", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 29, "en": "You've got the neighbours' letters!", "zh": "你居然把邻居们的所有信件全给拿上来了！", "note": "惊讶批评 neighbours' letters", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 30, "en": "I'm sure my examination results are here.", "zh": "我确信我的考试成绩单一定就在这堆信件里面。", "note": "坚定寻找 examination results", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 31, "en": "What kind of a challenge?", "zh": "这又是哪门子的奇葩挑战？", "note": "无奈询问 What kind of challenge", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 32, "en": "Stop thinking about your challenge and follow me.", "zh": "别再满脑子想你那破挑战了，快跟我过来！", "note": "强势打断 follow me", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 33, "en": "Oh, you think you can do better? — I know I can do better.", "zh": "呵，你以为你比我更在行？— 我肯定我比你强得多。", "note": "互不相让 do better", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 34, "en": "My father taught me.", "zh": "这手绝活可是我父亲亲手教我的。", "note": "家传手艺 father taught me", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 35, "en": "I need a man to fix the computer I bought.", "zh": "我需要找个维修师傅来把我新买的电脑修好。", "note": "求助维修 fix the computer", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 36, "en": "And I'd like him to be tall, dark, and handsome.", "zh": "另外，我希望他高大英俊、充满魅力。", "note": "经典择偶梗 tall, dark, handsome", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 37, "en": "At last, a real man!", "zh": "终于能来一个真正的男子汉了！", "note": "如释重负 a real man", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 38, "en": "I had to call a man to repair my new computer.", "zh": "我迫不得已只能打电话找人来修我的新电脑。", "note": "无奈倾诉 repair computer", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 39, "en": "What happened to it? — It was not like that before.", "zh": "电脑怎么会搞成这样？— 之前可绝不是这副德行的。", "note": "推卸责任 not like that before", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 40, "en": "Hector does not stand a chance.", "zh": "赫克托这回连一丝一毫赢的机会都没有了。", "note": "毫无胜算 not stand a chance", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 41, "en": "I've got all my friends to call you.", "zh": "我已经发动了我所有的女性朋友给你打电话了。", "note": "发动助攻 call you", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 42, "en": "I know what you're going to say, but it was like that when I bought it!", "zh": "我知道你想说什么，可我买回来的时候它本来就是这样的！", "note": "甩锅金句 like that when bought", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 43, "en": "It looks broken. — You can't repair it?", "zh": "它看起来完全报废损坏了。— 难道你修不好吗？", "note": "失望询问 broken", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 44, "en": "Well, how can you be a repairman then? — I'm not.", "zh": "那你凭什么干维修这一行啊？— 我本来就不是修电脑的。", "note": "荒唐反转 not a repairman", "b64": "", "src": "extra"}, {"l": 117, "lt": "Extra E17 网上冲浪", "i": 45, "en": "Good looking and intelligent: A rare combination.", "zh": "长得既帅气又有智慧：这在世上可真不多见。", "note": "赞美溢美 rare combination", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 1, "en": "What is the point of all that studying if I cannot get a job?", "zh": "如果读了那么多书却连一份工作都找不着，读书的意义何在？", "note": "求职困惑 What is the point", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 2, "en": "What is the point of having a car if you cannot park?", "zh": "如果连车都停不了，那买车还有什么意义？", "note": "停车难题 cannot park", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 3, "en": "I've just got a job as a traffic warden!", "zh": "我刚刚得到了一份工作，去当交通协管员/贴条交警！", "note": "宣布新工作 traffic warden", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 4, "en": "What is a traffic warden? Someone who spoils your day?", "zh": "什么是交通协管员？专门毁掉你美好一天的人吗？", "note": "戏谑吐槽 spoils your day", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 5, "en": "A traffic warden stops stupid people parking their stupid cars in stupid places!", "zh": "交通协管员就是阻止蠢人把蠢车停在蠢地方的人！", "note": "犀利反击 stupid places", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 6, "en": "It is good for the environment to reduce the cars on our roads.", "zh": "减少路上的汽车数量对保护环境大有裨益。", "note": "环保理念 environment", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 7, "en": "Hector, you could be the driver and I will be the traffic warden.", "zh": "赫克托，你来扮演违章司机，我来扮演交通协管员。", "note": "情景模拟 traffic warden", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 8, "en": "Sorry, emergency appointment! Bad leg!", "zh": "抱歉抱歉，我有紧急预约！我腿受了重伤！", "note": "违章借口 emergency appointment", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 9, "en": "Which leg? No, it's not me. It's my hamster.", "zh": "哪条腿？不，不是我腿伤，是我养的仓鼠伤了。", "note": "离谱借口 my hamster", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 10, "en": "Surely we can come to some arrangement?", "zh": "我们肯定能通融商量一下的吧？", "note": "试图通融 come to arrangement", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 11, "en": "Of course we can, sir. You can pay for the ticket!", "zh": "那当然可以了先生，您可以直接把罚单给缴了！", "note": "铁面无私 pay for ticket", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 12, "en": "Sorry, but I was late for lunch and there wasn't a place to park.", "zh": "抱歉，我赶着去吃午饭快迟到了，到处又没停车位。", "note": "常见借口 late for lunch", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 13, "en": "Surely we can sort this out when a beautiful woman meets a handsome man?", "zh": "当美女邂逅帅哥，我们总能私下解决这件小事的，对吧？", "note": "油腔滑调 sort this out", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 14, "en": "Well, you're in my little black book now, darling.", "zh": "好啊亲爱的，你的大名现在已经记在我的罚单黑名单上了。", "note": "幽默制裁 little black book", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 15, "en": "Hey, I've only been two minutes! — Well, I have started, so I'll finish.", "zh": "嘿，我才停了两分钟而已！— 抱歉，我笔已经落下了，就必须开完。", "note": "铁面贴条 only two minutes", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 16, "en": "Late ironing penalty: 20 pounds!", "zh": "逾期未熨烫衣服罚款：20英镑！", "note": "生活搞笑规矩 penalty", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 17, "en": "Late washing up penalty: five pounds.", "zh": "逾期未洗碗盘罚款：5英镑。", "note": "家务罚款 washing up", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 18, "en": "I need a drink. I don't believe it. She's clamped the fridge!", "zh": "我得喝口水。我真不敢相信，她居然把冰箱给上锁贴封条了！", "note": "爆笑高潮 clamped fridge", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 19, "en": "She's too serious about this traffic warden exam.", "zh": "她对这个交通协管员考试也未免太较真上头了。", "note": "过于较真 too serious", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 20, "en": "If I stop to talk to her, she gives me a parking ticket!", "zh": "我要是敢停下脚步跟她说话，她立刻就甩我一张违停罚单！", "note": "搞笑抱怨 parking ticket", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 21, "en": "Channel 9 is presenting the Miss Eurobabe beauty contest.", "zh": "第9频道即将举办‘欧洲宝贝’选美大赛！", "note": "选美赛事 beauty contest", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 22, "en": "And guess who wants to present the show? Hector!", "zh": "猜猜制片人想让谁来主持这场大赛？赫克托！", "note": "担任主持 present the show", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 23, "en": "It's my job to give you all the information about the girls.", "zh": "我的职责就是向你提供所有参赛选手的详细资料。", "note": "职场分工 information", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 24, "en": "Hector will need an interpreter to help him talk to all those babes.", "zh": "赫克托需要一个随身翻译来帮他跟那些美女聊天搭讪。", "note": "找借口蹭 babes", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 25, "en": "You're not getting involved in this show!", "zh": "你休想掺和进这档节目里来！", "note": "无情拒绝 not getting involved", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 26, "en": "It's a very important job. It's good for the environment.", "zh": "这是一份非常重要的职业，能减少路面拥堵、保护环境。", "note": "职业自豪 important job", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 27, "en": "There's some very stupid people out there.", "zh": "外头总有那么些愚不可及的违章司机。", "note": "日常感叹 stupid people", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 28, "en": "Nothing can go wrong.", "zh": "放一百个心，绝对出不了任何纰漏。", "note": "立Flag Nothing can go wrong", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 29, "en": "I'm going for my traffic warden exam. Are you expecting trouble?", "zh": "我这就去参加交通协管员考试了。— 你预备着要打硬仗吗？", "note": "全副武装 expecting trouble", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 30, "en": "There are a lot of difficult motorists out there.", "zh": "外头多的是蛮不讲理的难缠司机。", "note": "职业挑战 difficult motorists", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 31, "en": "Welcome to Channel 9's Eurobabe contest live!", "zh": "欢迎来到第9频道‘欧洲宝贝’选美大赛现场直播！", "note": "现场直播 contest live", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 32, "en": "So let's meet our lovely contestants eager to wear the crown.", "zh": "让我们有请各位渴望摘得桂冠的美丽佳丽登场！", "note": "选手登场 wear the crown", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 33, "en": "If you don't get off by the time I count to three, I will cut off your ears!", "zh": "等我数到三，你要是不立刻滚下台，我就割掉你的耳朵！", "note": "后台发飙 cut off your ears", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 34, "en": "This is why I didn't want you here!", "zh": "这就是我当初为什么死活不让你来现场的原因！", "note": "怒火攻心 didn't want you here", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 35, "en": "Miss England is where? She's been clamped!", "zh": "英格兰小姐在哪儿？她的车被人锁轮贴条给扣下了！", "note": "戏剧冲突 clamped", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 36, "en": "She won't leave her Porsche.", "zh": "她死活都不肯离开她的保时捷豪车。", "note": "豪车执念 Porsche", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 37, "en": "You have one simple job. Do not mess it up!", "zh": "你就这么一项简单的任务，千万别给我搞砸了！", "note": "严肃交代 Do not mess it up", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 38, "en": "We've got big problems. Miss England will not come here.", "zh": "我们碰上大麻烦了，英格兰小姐死活不肯过来了。", "note": "突发危机 big problems", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 39, "en": "She's broken a nail. — Oh, nasty.", "zh": "她指甲给折断了。— 哎哟，那可真是太‘严重’了。", "note": "讽刺娇气 broken a nail", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 40, "en": "Think of something, Nick, fast!", "zh": "快点给我想个招出来，尼克，动作快！", "note": "十万火急 Think of something", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 41, "en": "And we come to our last contestant: Miss England!", "zh": "下面登场的是本次大赛最后一位佳丽：英格兰小姐！", "note": "压轴登场 last contestant", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 42, "en": "What do you think you're doing? I meant a woman!", "zh": "你以为你自己在干什么？我说的是找个女人顶上！", "note": "惊呆质问 meant a woman", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 43, "en": "Nice legs, Nick! — Thanks, Annie.", "zh": "腿型挺漂亮的嘛，尼克！— 谢谢夸奖，安妮。", "note": "经典名场面 Nice legs", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 44, "en": "I want to represent England because I care about the environment.", "zh": "我渴望代表英格兰参赛，因为我心系环保与消除污染。", "note": "选美问答 represent England", "b64": "", "src": "extra"}, {"l": 118, "lt": "Extra E18 正合心意", "i": 45, "en": "And the winner of the Channel 9 Eurobabe contest is Miss England!", "zh": "荣获第9频道欧洲宝贝选美大赛总冠军的是——英格兰小姐！", "note": "赢得桂冠 the winner is", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 1, "en": "You know, I hate violence. — I hate violence too, but I love Ricky Chong!", "zh": "你知道的，我讨厌暴力。— 我也讨厌暴力，但我超级迷恋成龙！", "note": "偶像崇拜 Ricky Chong", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 2, "en": "We must teach Hector how to be English, not an English idiot.", "zh": "我们必须教赫克托如何做一个真正的英国绅士，而不是个笨蛋。", "note": "文化调侃 English idiot", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 3, "en": "Nick, why do you always use our number?", "zh": "尼克，你干嘛老是用我们家里的电话号码留给别人？", "note": "日常借用 use our number", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 4, "en": "You're so idiotic, stupid, vain: Choose one!", "zh": "你简直是蠢透了、笨极了、自恋死了：三选一吧！", "note": "好友吐槽 Choose one", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 5, "en": "I have just got an audition for the new Ricky Chong film!", "zh": "我刚刚得到了功夫巨星成龙新电影的试镜机会！", "note": "试镜机会 got an audition", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 6, "en": "As I was saying, you're so clever, wonderful, brilliant!", "zh": "正如我刚才所言：你真是太聪明、太棒、太有才了！", "note": "秒变态度 clever, brilliant", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 7, "en": "I always knew you'd make it to the top!", "zh": "我早就知道你迟早有一天会出人头地、登顶巅峰！", "note": "恭维吹捧 make it to the top", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 8, "en": "Wait a minute. He only has an audition.", "zh": "等等，他不过是刚捞到一个试镜机会而已嘛。", "note": "泼冷水 only an audition", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 9, "en": "Oh, I'm sure he'll get it. Then I can interview Ricky Chong!", "zh": "噢，我相信他肯定能拿下的，这样我就能专访成龙了！", "note": "满心期待 interview", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 10, "en": "Maybe Ricky will fancy me. — You? In your dreams!", "zh": "说不定成龙还会看上我呢。— 看上你？做你的白日梦去吧！", "note": "做白日梦 In your dreams", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 11, "en": "You'll have a house in London and he'll have a house in Hong Kong.", "zh": "你可以在伦敦买套大宅，而他在香港有一栋豪宅。", "note": "豪门幻想 house in London", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 12, "en": "I should get an Oriental style: New clothes!", "zh": "我得去换一身东方风情的造型：去买新衣服！", "note": "异域风情 Oriental style", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 13, "en": "Come shopping with me. — I can't. I have a group meeting.", "zh": "陪我去逛街购物吧。— 不行，我得去参加一个互助小组会议。", "note": "逛街邀约 group meeting", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 14, "en": "Well, I've been thinking about our relationship.", "zh": "那个，我最近一直在认真思考我们之间的感情关系。", "note": "严肃探讨 relationship", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 15, "en": "Channel 9 has to lose people. And guess who is the first person to go? You!", "zh": "第9频道要裁员减员了。猜猜谁是第一个被开除的？你！", "note": "职场危机 You're fired", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 16, "en": "If you get the interview, you keep your job. No pressure!", "zh": "只要你能搞到独家专访，你就能保住饭碗。没有任何压力哈！", "note": "职场重压 No pressure", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 17, "en": "Look, I've made you a cake. Try a piece.", "zh": "快看，我亲手给你做了一个大蛋糕。尝一小块吧。", "note": "下厨心意 made you a cake", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 18, "en": "Charlotte said you have to put some flour in the cake!", "zh": "电视上的主厨说，做蛋糕里面必须得放一些面粉（他放了真花）！", "note": "同音梗 flour vs flower", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 19, "en": "No, Hector: flour, not flower!", "zh": "不，赫克托：是面粉flour，不是鲜花flower！", "note": "经典谐音教学 flour not flower", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 20, "en": "Hey, I've got an audition for the new Ricky Chong film!", "zh": "嘿，我拿到了成龙新功夫电影的试镜了！", "note": "奔走相告 got an audition", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 21, "en": "Who is Ricky Chong? — He was in the Chinese restaurant, doesn't he?", "zh": "成龙是谁？— 他不就是中餐馆里的那个跑堂吗？", "note": "老外盲区 Chinese restaurant", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 22, "en": "Will you help me to prepare? — I would love to.", "zh": "你愿意帮我一起对戏准备试镜吗？— 我求之不得呢。", "note": "帮忙对戏 help me prepare", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 23, "en": "Look out Hollywood! Nick's your new man!", "zh": "好莱坞睁大眼睛瞧好吧！尼克就是你们冉冉升起的下一位巨星！", "note": "狂妄壮志 Look out Hollywood", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 24, "en": "Hector baked a cake with a real flower inside it!", "zh": "赫克托做蛋糕居然直接把一朵大鲜花活生生揉进了蛋糕里！", "note": "搞笑转述 flower inside", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 25, "en": "We are made for each other. I love everything Oriental.", "zh": "我们俩简直是天造地设的一对，我最痴迷东方文化的一切了。", "note": "盲目迷恋 made for each other", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 26, "en": "Violence makes me sick. — I totally agree, Richard.", "zh": "暴力让我恶心反胃。— 我举双手赞同你的看法，理查德。", "note": "共鸣反暴力 totally agree", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 27, "en": "You must come and meet my dog, Charlie. We have so much in common.", "zh": "你一定要来见见我的小狗查理，我们俩共同语言实在太多了。", "note": "寻找共鸣 in common", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 28, "en": "I think we should talk. — What do you want to talk about?", "zh": "我觉得我们该好好聊聊了。— 你想聊些什么呢？", "note": "严肃沟通 we should talk", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 29, "en": "I think we should see other people.", "zh": "我觉得我们还是暂时各自结识其他人、冷静一下吧。", "note": "委婉提分手 see other people", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 30, "en": "See other people? But I see other people: I see Bridget, Nick, the postman!", "zh": "见其他人？可我天天都在见其他人：布里吉特、尼克，还有邮递员！", "note": "爆笑字面理解 postman", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 31, "en": "Help me prepare my interview with Ricky Chong.", "zh": "快帮我演练一下怎么采访成龙吧。", "note": "采访演练 prepare interview", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 32, "en": "What kind of women do you like? — I like beautiful women like you.", "zh": "你喜欢哪种类型的女人？— 我最喜欢像你这样美若天仙的女人。", "note": "花言巧语 beautiful women", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 33, "en": "I want you to attack me! It must be a surprise.", "zh": "我想要你冷不防袭击我！动作必须出其不意。", "note": "功夫特训 attack me", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 34, "en": "So I must always be ready.", "zh": "这样我才能练就随时随地保持戒备的本能。", "note": "时刻警惕 always be ready", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 35, "en": "I am feeling good. I am feeling fit.", "zh": "我感觉状态好极了，我浑身充满活力！", "note": "自信满满 feeling fit", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 36, "en": "Let's see what you can do. You've got the part!", "zh": "让我们看看你能亮出什么绝活。恭喜你，你通过试镜拿到角色了！", "note": "通过试镜 got the part", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 37, "en": "I'm looking at the new Ricky Chong!", "zh": "我眼前站着的简直就是成龙二世！", "note": "夸大其词 new Ricky Chong", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 38, "en": "I met a new man, Richard. He is so sweet.", "zh": "我结识了一个新对象，叫理查德，他特别温柔体贴。", "note": "新欢登场 He is so sweet", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 39, "en": "He hates violence and loves animals.", "zh": "他深恶痛绝暴力，而且极其富有爱心地热爱小动物。", "note": "人设立体 hates violence", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 40, "en": "You have to be very professional to work with Ricky Chong.", "zh": "要想和成龙搭戏合作，你必须展现出极其顶尖的专业素养。", "note": "专业要求 professional", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 41, "en": "Ricky never talks at work. Very professional.", "zh": "成龙在片场工作时从不废话闲聊，这可真是太敬业专业了。", "note": "片场花絮 professional", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 42, "en": "What do you want me to do? — You just stand still.", "zh": "你想让我演什么戏份？— 你只要笔直站着挨打别动就行。", "note": "搞笑指令 stand still", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 43, "en": "We are partners: We fight the criminals together!", "zh": "我们可是生死搭档：我们是一起联手惩奸除恶的功夫战警！", "note": "英雄幻灭 partners", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 44, "en": "No, you play the stupid friend who gets beaten up.", "zh": "不，你演的是那个负责挨揍搞笑的大笨蛋跟班好友。", "note": "残酷真相 stupid friend", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 45, "en": "I taught Ricky a lot today.", "zh": "我今天在片场可给成龙上了好大一堂生动的课呢。", "note": "吹嘘死撑 taught Ricky", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 46, "en": "No Ricky, no interview. No interview, no job!", "zh": "见不到成龙，就拿不到专访。没有专访，饭碗就彻底砸了！", "note": "连锁反应 No job", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 47, "en": "Bridget, this is Ricky Chong! This is Richard!", "zh": "布里吉特，他就是成龙！他就是理查德！", "note": "惊天反转 This is Ricky Chong", "b64": "", "src": "extra"}, {"l": 119, "lt": "Extra E19 功夫小子", "i": 48, "en": "Hector, will you forgive me? — Of course.", "zh": "赫克托，你能原谅我之前的任性吗？— 那当然，我永远原谅你。", "note": "破镜重圆 forgive me", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 1, "en": "What are you watching? — It's a dog show.", "zh": "你在看什么电视节目？— 是个宠物名犬选美展。", "note": "日常闲聊 dog show", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 2, "en": "I didn't know you liked dogs. — I don't like dogs. I like those women with their dogs!", "zh": "我怎么不知道你还喜欢狗？— 我才不喜欢狗呢，我喜欢牵着狗的漂亮女士！", "note": "好色本性 lady dogs", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 3, "en": "You can enter the dog show this year and win 2,000 pounds.", "zh": "报名参加今年的名犬大赛，最高可斩获两千英镑大奖！", "note": "巨额奖金 win 2000 pounds", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 4, "en": "We must enter this dog show with Charlie.", "zh": "我们一定要带着小狗查理去报名参加这场大赛！", "note": "决定参赛 enter dog show", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 5, "en": "I'm meeting my new boyfriend tonight. — Boyfriend? Tell me everything!", "zh": "我今晚要和我的新男友约会。— 新男友？快一五一十全部招来！", "note": "八卦闺蜜 Tell me everything", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 6, "en": "Well, his name's Philip. He's very elegant.", "zh": "嗯，他叫菲利普，举止极其优雅从容。", "note": "新欢夸赞 very elegant", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 7, "en": "Do you like dog shows, Annie? — I hate them. They are horrible.", "zh": "安妮，你平时喜欢看狗狗选美赛吗？— 我最讨厌了，那种比赛残忍恶心死了。", "note": "态度对立 hate dog shows", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 8, "en": "You have to respect animals.", "zh": "生而为人，必须对动物心怀尊重。", "note": "动物保护 respect animals", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 9, "en": "We will have to train Charlie ourselves without Annie knowing.", "zh": "我们必须在安妮不知情的情况下，偷偷给查理做特训。", "note": "秘密训练 without knowing", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 10, "en": "How to Train Your Dog: Now we can train Charlie!", "zh": "《训狗速成秘籍》：这下我们能好好调教查理了！", "note": "训狗指南 train your dog", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 11, "en": "Charlie, here boy! Sit! Good dog, good trainer!", "zh": "查理，快过来好孩子！坐下！真乖，训得真棒！", "note": "口令训练 Sit", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 12, "en": "Annie has taken him to the vet: The animal doctor.", "zh": "安妮已经带它去宠物医院看兽医了。", "note": "词汇讲解 vet", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 13, "en": "Well, we can still start training! — We can? How?", "zh": "那咱们照样可以开始训练啊！— 狗都不在怎么训？", "note": "无厘头脑洞 start training", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 14, "en": "Sit! I said sit! Good boy! Now, roll over!", "zh": "坐下！我让你坐下！真乖！现在，在地上打个滚！", "note": "把人当狗训 roll over", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 15, "en": "Roll over, Hector! Good boy, good boy!", "zh": "打滚，赫克托！真乖，真是个听话的好孩子！", "note": "爆笑互训 Good boy", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 16, "en": "Now I want to be the dog! — No, I am the dog!", "zh": "现在该轮到我来演狗了！— 不行，我才是狗！", "note": "争当狗狗 I am the dog", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 17, "en": "What are they doing? — Well, this is a new type of yoga: Dog yoga!", "zh": "他们俩这到底是在干嘛？— 呃，这是新型瑜伽：狗狗瑜伽！", "note": "当场圆谎 Dog yoga", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 18, "en": "Are dogs allowed on the sofa?", "zh": "你们家沙发上平时允许狗爬上去吗？", "note": "嫌弃做派 allowed on sofa", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 19, "en": "I don't like that man. — I don't think he likes you either.", "zh": "我可一点都不喜欢那家伙。— 我看他八成也瞧不上你。", "note": "互看不爽 don't like that man", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 20, "en": "He's everything I want: elegant, handsome, intelligent, and very unlike Nick.", "zh": "他完全符合我的一切要求：儒雅、帅气、聪明，而且一点都不像尼克。", "note": "拉踩前任 unlike Nick", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 21, "en": "I know how to earn two thousand pounds with Charlie: winning a dog show!", "zh": "我知道怎么用查理赚到两千英镑了：拿下名犬选美冠军！", "note": "发财计划 winning a dog show", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 22, "en": "I'll buy Charlie a nice ribbon. Then the lady dogs will love him.", "zh": "我去给查理买个漂亮的缎带蝴蝶结，那些母狗见了一定迷死它。", "note": "打扮赛犬 nice ribbon", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 23, "en": "Where's my necklace then? — I haven't got your necklace!", "zh": "那我的项链去哪儿了？— 我才没拿你的项链！", "note": "失窃争吵 necklace", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 24, "en": "Don't touch my things! — I didn't touch your things!", "zh": "少碰我的私人物品！— 我根本连碰都没碰过你的东西！", "note": "室友翻脸 Don't touch", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 25, "en": "Annie is so angry. What have you done? — Me? Nothing!", "zh": "安妮火气大得吓人。你干了什么好事？— 我？我什么都没干啊！", "note": "无辜背锅 What have you done", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 26, "en": "Women love Charlie. What a handsome dog you have!", "zh": "姑娘们对查理喜欢得不得了：多么英俊漂亮的一条狗啊！", "note": "借狗搭讪 handsome dog", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 27, "en": "Where is he? Charlie the dog?", "zh": "他人呢？查理这条狗哪儿去了？", "note": "突然发现狗丢了 Where is he", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 28, "en": "He was only tied up at that lamppost for a bit!", "zh": "我不过就把它在路灯杆子上随手拴了一小会儿而已！", "note": "粗心大意 tied up", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 29, "en": "Talking of dogs, where is Charlie?", "zh": "说到狗，查理到底在什么地方？", "note": "追问狗下落 Talking of dogs", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 30, "en": "He's asleep! He's ill! He's busy! He's having his hair cut!", "zh": "它睡着了！它病了！它正忙着！它剪毛去了！", "note": "连环扯谎 having hair cut", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 31, "en": "We have lost Annie's dog Charlie, and the dog show is today!", "zh": "我们把安妮的狗给弄丢了，而且今天就是比赛日！", "note": "十万火急 dog show today", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 32, "en": "Lots of my things are missing. I think she's selling them on the internet!", "zh": "我的好多首饰都莫名其妙不见了，我怀疑她拿去网上倒卖了！", "note": "荒唐怀疑 selling on internet", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 33, "en": "The police have found our dog!", "zh": "警察打电话说找到了我们家走丢的狗！", "note": "警方寻回 found our dog", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 34, "en": "Where are you? — The police station!", "zh": "你人在哪儿？— 警察局派出所！", "note": "惊愕地点 police station", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 35, "en": "You took a dog from an old woman? Nick, how could you?", "zh": "你居然在大街上抢了一位老太太的狗？尼克，你怎么干得出这事？", "note": "荒唐误会 took a dog", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 36, "en": "That woman, she really went for you!", "zh": "那个老太太刚才简直追着你下死手啊！", "note": "老太发威 went for you", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 37, "en": "I'm meeting Philip tonight and I can't find my earrings.", "zh": "我今晚要和菲利普约会，可我死活找不着我的耳环了。", "note": "首饰失踪 earrings", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 38, "en": "I haven't stolen anything! — You're a thief! — I am not a thief!", "zh": "我什么都没偷！— 你就是个小偷！— 我才不是小偷！", "note": "激烈互撕 thief", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 39, "en": "The dog show winner is Charlie with his trainers, Hector and Nick!", "zh": "本届名犬大赛总冠军是查理，以及它的训导师赫克托与尼克！", "note": "夺冠揭晓 dog show winner", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 40, "en": "We won! We won!", "zh": "我们赢了！我们拿冠军啦！", "note": "狂喜庆祝 We won", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 41, "en": "You hate dog shows! — Well, if Charlie wins, then that's different.", "zh": "你平时不是最恨狗狗选美吗！— 哎呀，要是查理赢了，那可就另当别论了。", "note": "双标反转 that's different", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 42, "en": "We won two thousand pounds to spend in Dog's Heaven!", "zh": "我们赢的是两千英镑——‘狗狗天堂’宠物用品代金券！", "note": "爆笑奖品 Dog's Heaven", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 43, "en": "Get off me! What is he doing? Get off me!", "zh": "快把它从我身上弄开！它要干什么？放开我！", "note": "恶犬扑食 Get off me", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 44, "en": "My jewelry! My photo frame! He's carrying our things!", "zh": "我的珠宝！我的相框！他身上全揣着我们失窃的东西！", "note": "真相大白 jewelry", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 45, "en": "You're the thief!", "zh": "原来你才是那个真正的偷窃惯犯！", "note": "当场抓包 You're the thief", "b64": "", "src": "extra"}, {"l": 120, "lt": "Extra E20 苦尽甘来", "i": 46, "en": "He took souvenirs to remind him of me: So romantic!", "zh": "他只是偷拿了些纪念品回去睹物思人而已：真是太浪漫了！", "note": "神级恋爱脑 So romantic", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 1, "en": "I am going to hypnotise you! — Hypnotise?", "zh": "我打算对你们实施催眠！— 催眠？", "note": "催眠术 hypnotise", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 2, "en": "You are feeling very sleepy. You are a baby.", "zh": "你感到眼皮极其沉重，困意袭来……你现在是一个婴儿。", "note": "催眠指令 very sleepy", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 3, "en": "Hypnotism can help you with your problems. — I don't have any problems!", "zh": "催眠能帮你解开心灵困扰。— 我健康得很，一点困扰都没有！", "note": "催眠疗愈 help with problems", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 4, "en": "Now close your eyes and relax.", "zh": "现在闭上双眼，全身放松。", "note": "冥想放松 relax", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 5, "en": "When you hear that word, you are going to react: Butterfly!", "zh": "每当你听到这个触发词，你就会立刻做出应激反应：蝴蝶！", "note": "催眠触发词 Butterfly", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 6, "en": "No one can control the great minds of Hector and Nick!", "zh": "谁也别想控制赫克托与尼克这两个绝顶聪明的大脑！", "note": "迷之自傲 great minds", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 7, "en": "A hypnotic state can last for two days.", "zh": "催眠留下的潜意识状态可以持续整整两天之久。", "note": "持续潜意识 hypnotic state", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 8, "en": "If someone says the word butterfly in the next two days...", "zh": "在接下来的两天里，要是有人无意中说出‘蝴蝶’这个词……", "note": "立下悬念 trigger word", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 9, "en": "Pin the tail on the donkey: Great game, poor donkey!", "zh": "给驴贴尾巴游戏：多棒的游戏啊，可怜的驴子！", "note": "派对经典游戏 Pin the tail", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 10, "en": "Top class entertainers: That's us! We will be party entertainers to rich children for loads of money!", "zh": "顶级演艺达人：就是我们！我们要给富家子弟当派对艺人，大赚一笔！", "note": "发财宏图 loads of money", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 11, "en": "Make your child's party go with a bang! We are top class children's entertainers.", "zh": "让您孩子的生日派对燃爆全场！我们是顶尖的儿童派对艺人。", "note": "宣传广告 go with a bang", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 12, "en": "Book Posh Parties for the best party in the world. Only millionaires need apply!", "zh": "预订‘贵族派对’，享受全球最顶级盛宴。非百万富翁请勿扰！", "note": "奢华定位 Only millionaires", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 13, "en": "I think you'll be lucky to get one reply.", "zh": "我看你们要是能收到哪怕一条咨询回复，都算走狗屎运了。", "note": "闺蜜讽刺 lucky to get one", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 14, "en": "You know who it is, don't you? Victoria, Lucas's mother!", "zh": "你知道打电话来的是谁吗？是维多利亚，小卢卡斯的妈妈！", "note": "熟人来电 Victoria", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 15, "en": "She loves fairies. Well, I have just the fairy for you: Princess Nicky!", "zh": "她女儿最喜欢仙女了。正好，我有人选：尼基小仙女公主！", "note": "男扮女装 Princess Nicky", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 16, "en": "Of course I know what little girls like. I used to be one myself!", "zh": "我当然深知小女孩喜欢什么，我自己当年也曾是小姑娘呢！", "note": "假装女声 I used to be one", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 17, "en": "Dressed as a fairy princess? What will Victoria say? — Who cares! This is my chance to get into Hollywood!", "zh": "仙女公主？维多利亚会怎么看？— 管她呢！这是我进军好莱坞的天赐良机！", "note": "好莱坞之梦 into Hollywood", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 18, "en": "What can you do to entertain children? — I can juggle!", "zh": "你到底会表演什么绝活逗小孩子？— 我会杂耍扔球！", "note": "杂耍绝技 I can juggle", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 19, "en": "Children and I do not work well together.", "zh": "我和小孩子天生八字不合、水火不容。", "note": "讨厌小孩 not work well", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 20, "en": "It's only the home of George Dukas, with the children of Hollywood stars!", "zh": "那可是好莱坞大导演乔治·杜卡斯的豪宅，满屋子都是大牌明星子女！", "note": "名流派对 Hollywood stars", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 21, "en": "I feel ridiculous! — You feel ridiculous? What about me?", "zh": "我觉得自己简直荒唐滑稽透顶了！— 你荒唐？那你看看我成什么样了！", "note": "女装尴尬 feel ridiculous", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 22, "en": "Acting is going great. This is just a temporary job.", "zh": "我的演艺事业正蒸蒸日上呢，这只是份临时体验生活的工作。", "note": "死要面子 temporary job", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 23, "en": "He's next door chatting to Catherine Zeta-Jones, Orlando Bloom, and Jude Law.", "zh": "他正在隔壁房间跟凯瑟琳·泽塔-琼斯、奥兰多·布鲁姆、裘德·洛闲聊呢。", "note": "众星云集 Hollywood stars", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 24, "en": "Nick has made me help him with his silly children's party.", "zh": "尼克硬逼着我帮他操办这场愚蠢的儿童派对。", "note": "被迫营业 silly party", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 25, "en": "Worse still, I'm dressed as a fairy!", "zh": "更惨绝人寰的是，我居然还被逼穿得像个仙女！", "note": "被迫穿裙子 dressed as fairy", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 26, "en": "Princess Hectoretta is going to show you a magic trick!", "zh": "赫克托莱塔小仙女即将为大家表演一个惊天魔术！", "note": "魔术表演 magic trick", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 27, "en": "Now would you like to meet Mr. Whizzy?", "zh": "现在小朋友们想见见威齐先生吗？", "note": "道具兔子 Mr. Whizzy", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 28, "en": "Now Daisy, is Mr. Whizzy in the hat?", "zh": "黛西，快看看威齐先生在不在帽子里面？", "note": "魔术帽子 in the hat", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 29, "en": "Now give the hat a magic tap. Not too hard!", "zh": "现在用魔法棒轻轻敲击一下帽子。别太用力！", "note": "轻敲帽子 magic tap", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 30, "en": "You've got hairy legs and a hairy chest!", "zh": "你腿上长满了粗毛，胸口也毛茸茸的！", "note": "童言无忌 hairy legs", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 31, "en": "That's not a very nice thing to say about Tinkerbell!", "zh": "小朋友，这么说一位可爱的小仙女可太不礼貌了！", "note": "强行挽尊 Tinkerbell", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 32, "en": "Now, I'm going to make someone disappear!", "zh": "现在，我要把一个人变消失掉！", "note": "大变活人 disappear", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 33, "en": "Daisy, do you want to be part of the magic trick?", "zh": "黛西，你想来亲自参与这个神奇的魔术吗？", "note": "互动邀请 part of trick", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 34, "en": "Now in you go. We say the magical words: Hey presto!", "zh": "快钻进去吧。我们一起念出魔法密咒：变！", "note": "魔术咒语 Hey presto", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 35, "en": "She must be having a wonderful time in the magical land.", "zh": "她现在一定正在魔法仙境里玩得乐不思蜀呢。", "note": "魔术掩饰 magical land", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 36, "en": "It's time to come home now, Daisy!", "zh": "好啦黛西，是时候该回到现实世界啦！", "note": "唤回孩子 time to come home", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 37, "en": "Where is Daisy? Where is she?", "zh": "黛西去哪儿了？她人到底跑哪儿去了？", "note": "当场失踪 Where is Daisy", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 38, "en": "Your mind is like a butterfly... — Butterfly?!", "zh": "你的思绪轻盈得就像一只蝴蝶……— 蝴蝶？！", "note": "触发催眠 butterfly", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 39, "en": "Whatever you do, do not mention the word butterfly!", "zh": "无论如何，千万千万别当着他们的面提‘蝴蝶’这个词！", "note": "紧急警告 do not mention", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 40, "en": "They might behave strangely. Stranger than usual? — Yes!", "zh": "他们可能会行为反常。— 比平时还要更神经兮兮吗？— 没错！", "note": "行为反常 Stranger than usual", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 41, "en": "We were doing this magic trick, and we lost her!", "zh": "我们刚才在表演大变活人魔术，结果把寿星给搞丢了！", "note": "闯大祸 lost her", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 42, "en": "I'm calling the police!", "zh": "我现在立刻就打电话报警抓你们！", "note": "惊恐报警 calling police", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 43, "en": "She was in Princess Nicky's bath!", "zh": "她其实一直躲在尼基公主的浴缸里玩水呢！", "note": "虚惊一场 in the bath", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 44, "en": "Well then, you won't mind that I put parking tickets on four Mercedes, five Ferraris, and two Porsches outside!", "zh": "行啊，既然不给劳务费，那你肯定也不介意外面违停的四辆奔驰、五辆法拉利和两辆保时捷全被贴了罚单吧！", "note": "贴条女侠控场 parking tickets", "b64": "", "src": "extra"}, {"l": 121, "lt": "Extra E21 演艺达人", "i": 45, "en": "Surely we can come to some kind of an arrangement...", "zh": "好商量，我们之间凡事总归是可以通融协商的嘛……", "note": "当场秒怂 come to arrangement", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 1, "en": "I've just been to see Rose Marie: My fortune teller!", "zh": "我刚去拜访了露丝·玛丽：我的算命大师！", "note": "算命占卜 fortune teller", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 2, "en": "She says I'm going to meet a tall, dark, handsome stranger.", "zh": "她说我命中注定要邂逅一位身材高大英俊的神秘异性。", "note": "经典算命梗 handsome stranger", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 3, "en": "When? She didn't say. Where? She didn't say.", "zh": "什么时候？她没说。在哪里？她也没说。", "note": "含糊其辞 didn't say", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 4, "en": "Today, you will be in for a big surprise.", "zh": "今天，你将会迎来一个意想不到的大惊喜。", "note": "星座运势 big surprise", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 5, "en": "You must be psychic! — Someone who can see the future.", "zh": "你一定是有通灵超能力吧！— 就是能预见未来的人。", "note": "通灵特异功能 psychic", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 6, "en": "The death card: It's Bridget with no makeup!", "zh": "塔罗死神牌：这分明就是布里吉特纯素颜没化妆的样子！", "note": "毒舌吐槽 no makeup", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 7, "en": "Like having the palm of your hand read: Palmistry.", "zh": "就跟让人看手相、读手纹一样道理。", "note": "看手相 palm read", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 8, "en": "Come here, give me your hand. I'll give you a lesson.", "zh": "过来，把手伸出来，我来给你上一堂手相课。", "note": "手相教学 give hand", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 9, "en": "This one is your lifeline. This one is your love line.", "zh": "这一条是你的生命线，这一条是你的感情线。", "note": "生命线感情线 lifeline, love line", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 10, "en": "And this one is your punchline!", "zh": "而这一记，就是你的‘一拳揍上去’线！", "note": "双关谐音梗 punchline", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 11, "en": "Bridget, it's my tall, dark, handsome stranger. Get your own!", "zh": "布里吉特，这是我命中注定的高富帅，想要你自己找去！", "note": "抢男人 Get your own", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 12, "en": "This week, beware of black hair and the number three.", "zh": "本周预警：切忌提防黑发与数字‘三’。", "note": "神秘预言 beware of", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 13, "en": "That means three babes with black hair are going to chase me!", "zh": "那意思不就是说：将会有三位黑发靓妹疯狂倒追我嘛！", "note": "自恋曲解 three babes", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 14, "en": "Put that umbrella down! It's very unlucky.", "zh": "快把室内撑开的伞收起来！在英国室内撑伞极不吉利。", "note": "英国迷信 umbrella indoors", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 15, "en": "Let me look into my crystal ball. — Annie, that's a goldfish bowl!", "zh": "让我好好端详一下我的水晶球。— 安妮，那是个金鱼缸！", "note": "搞笑穿帮 goldfish bowl", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 16, "en": "I've lost my marbles! — Oh dear, Bernard's lost his marbles!", "zh": "我把我的小弹珠弄丢了！— 天哪，伯纳德脑子彻底短路发疯了！", "note": "双关习语 lost his marbles", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 17, "en": "Oh, you mean Marbles, your cat!", "zh": "噢，你指的是‘弹珠’——你养的那只猫啊！", "note": "解释名字 Marbles the cat", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 18, "en": "Today is Halloween, and I'm practicing my psychic skills.", "zh": "今天是万圣节前夜，我正在苦练我的通灵预言神技。", "note": "万圣节氛围 psychic skills", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 19, "en": "Tonight, we are all going to a Halloween party. I can't wait!", "zh": "今晚我们大家都要盛装出席万圣节变装派对，我都等不及了！", "note": "派对期待 I can't wait", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 20, "en": "This is a true story about a man and wife on their honeymoon.", "zh": "这是一个关于一对新婚夫妇在蜜月旅行中发生的真实怪谈。", "note": "鬼故事开头 true story", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 21, "en": "The wife broke a mirror, which means seven years' bad luck.", "zh": "妻子不慎打碎了镜子，在西方这意味着倒霉七年。", "note": "打破镜子 bad luck", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 22, "en": "Just then, they ran out of petrol.", "zh": "偏偏就在这时，车子的汽油彻底耗尽抛锚了。", "note": "半路抛锚 out of petrol", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 23, "en": "He heard a noise on the roof of the car. It got louder.", "zh": "他听见汽车车顶上传来一阵阵怪异声响，声音越来越大。", "note": "恐怖氛围 roof of car", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 24, "en": "He saw a madman holding his wife's head!", "zh": "他骇然看见一个疯子手里拎着他妻子的头颅！", "note": "恐怖高潮 saw a madman", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 25, "en": "Tell us another! — No, don't! It was a bit dull, wasn't it?", "zh": "再讲一个嘛！— 别讲了！刚才那故事挺乏味的，不是吗？", "note": "嘴硬害怕 bit dull", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 26, "en": "There are three apples. Big deal!", "zh": "这儿有三颗苹果。切，有什么大惊小怪的！", "note": "数字三 three apples", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 27, "en": "Keep calm!", "zh": "保持冷静，千万别慌！", "note": "自我安慰 Keep calm", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 28, "en": "I cannot get this knife into the pumpkin. Can you?", "zh": "我切不动这个大南瓜，你能帮我刻南瓜灯吗？", "note": "刻南瓜灯 knife into pumpkin", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 29, "en": "Hector told us a ghost story today. It was scary.", "zh": "赫克托今天给我们讲了个鬼故事，还真挺毛骨悚然的。", "note": "承认害怕 It was scary", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 30, "en": "Nothing scares me!", "zh": "世界上根本没有任何东西能吓唬得到我！", "note": "虚张声势 Nothing scares me", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 31, "en": "Bridget said: Beware of the number three.", "zh": "布里吉特说过：要时刻当心数字‘三’。", "note": "回想警示 Beware of three", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 32, "en": "Three children playing trick-or-treat!", "zh": "正好有三个讨糖果的小孩在大喊‘不给糖就捣蛋’！", "note": "万圣习俗 trick-or-treat", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 33, "en": "I even saw a black cat! It's all too much.", "zh": "我甚至还亲眼撞见了一只黑猫！这一切巧合实在太令人发毛了。", "note": "黑猫迷信 black cat", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 34, "en": "Those witches were very cute. I think the small one fancied you.", "zh": "刚才派对上的几个小女巫挺可爱的，那个矮个的好像看上你了。", "note": "调侃女巫 witches", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 35, "en": "The lights have gone out! It must be the storm, a power cut!", "zh": "所有的灯全灭了！一定是外面的暴风雨导致大停电了！", "note": "暴风雨停电 power cut", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 36, "en": "What was that? Who was that?", "zh": "刚才是那是啥动静？门口站着的到底是谁？", "note": "惊弓之鸟 Who was that", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 37, "en": "What's the matter, boys? Are you scared of the dark?", "zh": "怎么了男子汉们？难道你们怕黑吗？", "note": "戏弄胆小鬼 scared of dark", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 38, "en": "Let's get the Ouija board out!", "zh": "把通灵板/笔仙占卜盘拿出来玩吧！", "note": "通灵游戏 Ouija board", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 39, "en": "D-E-P-A-R-T: Depart! Depart means dead!", "zh": "拼出来了：D-E-P-A-R-T，离世！Depart意思是死亡/离世！", "note": "拼字惊魂 Depart", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 40, "en": "Didn't your horoscope say: Beware of the number three?", "zh": "你的星座运势里不是清清楚楚写着要提防数字‘三’吗？", "note": "印证预言 number three", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 41, "en": "Hector, do you believe in horoscopes? — Of course not, they're silly.", "zh": "赫克托，你平时相信星座那一套吗？— 当然不信，蠢透了。", "note": "嘴硬否认 silly", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 42, "en": "What was that noise? — Probably the wind.", "zh": "那又是什么声响？— 大概是窗外刮的大风吧。", "note": "疑神疑鬼 Probably wind", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 43, "en": "Hector, can I get into your bed? — Okay.", "zh": "赫克托，我能钻进你的被窝里一起睡吗？— 行吧。", "note": "胆小同床 get into your bed", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 44, "en": "There is something touching my legs! But it's not me!", "zh": "被子里有东西在蹭我的大腿！可那不是我的手！", "note": "床底惊魂 touching legs", "b64": "", "src": "extra"}, {"l": 122, "lt": "Extra E22 惊魂古堡", "i": 45, "en": "Has the cat got your tongue?", "zh": "怎么啦，猫把你的舌头给叼走了吗（怎么吓得哑口无言了）？", "note": "经典习语 got your tongue", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 1, "en": "Tell the truth or do a dare!", "zh": "选真心话，还是选大冒险！", "note": "派对游戏 Truth or dare", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 2, "en": "I dare you to kiss me!", "zh": "我大冒险命令你亲我一下！", "note": "大胆冒险 dare to kiss", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 3, "en": "I dare you to copy someone in this room.", "zh": "我大冒险罚你现场模仿这个房间里的某个人。", "note": "模仿他人 copy someone", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 4, "en": "Why not the truth? Nobody wants to speak the truth.", "zh": "干嘛不选真心话？大家都害怕说出大实话。", "note": "直击人心 speak the truth", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 5, "en": "I dare all of you to speak the truth for a whole day!", "zh": "我向你们所有人挑战：整整一天二十四小时必须只讲大真话！", "note": "全天真心话 a whole day", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 6, "en": "No lies! 24 hours of truth.", "zh": "绝不许撒半句谎话！整整24小时的绝对真实。", "note": "不许撒谎 No lies", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 7, "en": "We buy the winner dinner for two at The Ivy restaurant.", "zh": "我们自掏腰包请最后的赢家在艾维高档餐厅享用双人豪华晚宴！", "note": "胜者奖励 The Ivy", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 8, "en": "You will tell the truth, the whole truth, and nothing but the truth.", "zh": "你要如实陈述真情，句句属实，毫无隐瞒。", "note": "法庭宣誓梗 whole truth", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 9, "en": "The truth is, on Thursdays, I never go shopping. I just take your food!", "zh": "真相是：每逢周四我从没买过菜，我全是直接偷吃你的食物！", "note": "室友自白 take your food", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 10, "en": "Let's use the truth to make our relationship stronger.", "zh": "让我们用坦诚相待的真话，使我们的感情变得更牢不可破吧。", "note": "自作聪明 stronger", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 11, "en": "Write things I don't like about Hector.", "zh": "列出那些我看不惯赫克托的缺点清单。", "note": "罗列缺点 things I don't like", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 12, "en": "You don't like my carrot cake? But you always eat it!", "zh": "你居然不喜欢吃我做的胡萝卜蛋糕？那你平时干嘛全吃光了！", "note": "伤心质问 carrot cake", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 13, "en": "I didn't want to upset you.", "zh": "我之前不是不想惹你伤心难过嘛。", "note": "善意谎言 upset you", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 14, "en": "Well, now I am very cross! See, you're shouting again!", "zh": "哼，我现在可是真生气了！— 瞧，你又在大喊大叫了！", "note": "恼羞成怒 shouting again", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 15, "en": "Calm down, please, Annie.", "zh": "请你先冷静平静一下，安妮。", "note": "安抚情绪 Calm down", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 16, "en": "No, I don't want to see you. Goodbye.", "zh": "不，我一点都不想见到你，再见！", "note": "果断拒见 don't want to see you", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 17, "en": "Telling the truth: Have you ever fancied Bridget?", "zh": "讲真话：你以前有没有对布里吉特动过歪心思、迷过她？", "note": "灵魂拷问 fancied Bridget", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 18, "en": "Tell the truth: You do look fat in those trousers.", "zh": "说大实话：你穿这条裤子确实显得很胖。", "note": "致命真话 look fat in trousers", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 19, "en": "I can't change clothes. I don't have time.", "zh": "我没时间再重新换衣服了。", "note": "赶时间 don't have time", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 20, "en": "Don't forget: One day of truth!", "zh": "别忘了规矩：今天可是真话日！", "note": "提醒约定 One day of truth", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 21, "en": "Last night was horrible. We played truth or dare.", "zh": "昨晚简直是一场噩梦，我们玩了真心话大冒险。", "note": "痛苦回忆 horrible", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 22, "en": "I had to tell our neighbour Bernard that I fancied him!", "zh": "我居然被迫向我们的邻居伯纳德大叔表白说我暗恋他！", "note": "尴尬冒险 fancied him", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 23, "en": "This is a commercial for yoghurt: Yuppie Yoghurt.", "zh": "这是一支酸奶商业电视广告：‘雅痞酸奶’。", "note": "广告拍摄 commercial", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 24, "en": "This is the most delicious yoghurt in the world.", "zh": "这可是全世界最美味可口的酸奶了。", "note": "广告台词 most delicious", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 25, "en": "We want you to eat some and then say: Mmm, delicious!", "zh": "我们要你大口吃下一勺，然后陶醉地说：‘嗯，太好吃了！’", "note": "拍摄要求 Mmm delicious", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 26, "en": "45 minutes late! What happened this time?", "zh": "足足迟到了45分钟！这次又编了什么借口？", "note": "上司训斥 late", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 27, "en": "No, I'm late because I overslept.", "zh": "没借口，我迟到纯粹是因为我自己睡过头了。", "note": "真话暴击 overslept", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 28, "en": "You know Channel 9 wants new talent. Have you found any?", "zh": "你知道第9频道正急需发掘新面孔。你找到有潜力的苗子了吗？", "note": "发掘新人 new talent", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 29, "en": "A new presenter? Who? — Me!", "zh": "新主持人？谁啊？— 我自己！", "note": "毛遂自荐 Me", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 30, "en": "The truth: It's disgusting! Do I get the part? — Next!", "zh": "说大实话：这酸奶难吃恶心死了！我能拿到这个角色吗？— 下一位！", "note": "真话砸饭碗 It's disgusting", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 31, "en": "At least I don't have to eat that again.", "zh": "不过至少我再也不用逼自己吃那恶心的酸奶了。", "note": "自我安慰 don't have to eat", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 32, "en": "I've got a date with Bridget. That's right.", "zh": "我和布里吉特有约会，千真万确。", "note": "意外约会 a date with Bridget", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 33, "en": "Eunice is an ugly, bad-tempered witch!", "zh": "尤妮斯就是个奇丑无比、脾气暴躁的老巫婆！", "note": "闺蜜吐槽 bad-tempered witch", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 34, "en": "Old boyfriends: First John, now Kevin. What a coincidence.", "zh": "前男友们：先是约翰，现在又是凯文。真是太巧合了。", "note": "前任扎堆 What a coincidence", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 35, "en": "The problem is, I lost a job advertising yoghurt. I told them it tastes disgusting!", "zh": "问题是我把酸奶广告代言丢了，因为我当面告诉他们酸奶恶心透了！", "note": "大实话代价 tastes disgusting", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 36, "en": "It's very difficult to tell the truth at work all the time.", "zh": "在职场工作中要从头到尾讲大实话，简直太难了。", "note": "职场感悟 difficult to tell truth", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 37, "en": "How dare you call me a witch!", "zh": "你好大的胆子，居然敢骂我是个巫婆！", "note": "上司震怒 How dare you", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 38, "en": "Did you send that message? — No, someone took my phone.", "zh": "那条短信到底是不是你发的？— 不是，有人拿走了我的手机。", "note": "如实辩解 took my phone", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 39, "en": "So, what do you think of me? — The truth: You are an ugly, bad-tempered witch!", "zh": "那你真实心里是怎么看我的？— 说真话：你就是个丑陋、暴躁的老巫婆！", "note": "绝杀直球 bad-tempered witch", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 40, "en": "Honesty is a great quality. I hope honesty will help you when you look for a new job: You're fired!", "zh": "诚实是个优良品质。希望你在重新找工作时诚实能帮到你：你被解雇了！", "note": "经典开除 You're fired", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 41, "en": "I think you have the most beautiful eyes I have ever seen in my life.", "zh": "我认为你拥有我这辈子所见过的最美丽动人的双眼。", "note": "深情挽回 beautiful eyes", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 42, "en": "I finished with you because you have no personality, no money, and no sense of humour!", "zh": "当年我甩了你，就是因为你没个性、没金钱、而且毫无幽默感！", "note": "毒舌分手理由 no sense of humour", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 43, "en": "I didn't text you! Ziggy stole my phone and sent those messages!", "zh": "我根本没给你发过短信！是齐吉偷了我手机恶作剧乱发的！", "note": "真相大白 Ziggy stole phone", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 44, "en": "He'll make a perfect weather man. Maybe you can have your job back!", "zh": "他简直是完美的天气预报主持人！也许你能重新官复原职了！", "note": "峰回路转 perfect weather man", "b64": "", "src": "extra"}, {"l": 123, "lt": "Extra E23 真心话大冒险", "i": 45, "en": "So, do I get a job too?", "zh": "那这么说来，我也能顺便分到一份工作吗？", "note": "趁机讨要 do I get a job", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 1, "en": "Eunice wants some building work done, and guess who has to organise it?", "zh": "尤妮斯要把屋子装修翻新，猜猜谁得负责操办？", "note": "职场杂活 organise building", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 2, "en": "We're having a street party to protest and stop the cars.", "zh": "我们在街头举办街区派对，抗议并阻断机动车通行。", "note": "环保街头派对 street party", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 3, "en": "It belonged to my grandmother. It's very special to me.", "zh": "这是我祖母留给我的传家宝，对我来说意义非凡。", "note": "传家宝 very special", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 4, "en": "Captain Chip Harding: Pilot extraordinaire!", "zh": "奇普·哈丁机长：非同凡响的传奇王牌飞行员！", "note": "霸气头衔 Pilot extraordinaire", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 5, "en": "Women love uniform!", "zh": "女人们对制服诱惑完全没有抵抗力！", "note": "制服魅力 love uniform", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 6, "en": "I'm in a play for a theatre festival in Paris.", "zh": "我要参加巴黎戏剧节的一部话剧演出。", "note": "戏剧节 theatre festival", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 7, "en": "Hector, come fly with me!", "zh": "赫克托，跟我一起比翼双飞吧！", "note": "经典双关 come fly with me", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 8, "en": "Did you miss me, sweet thing?", "zh": "有没有想我呀，小甜心？", "note": "肉麻台词 sweet thing", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 9, "en": "Ladies and gentlemen, this is your Captain Chip Harding speaking.", "zh": "女士们先生们，我是本次航班的奇普·哈丁机长。", "note": "机长广播 speaking", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 10, "en": "Exits are here, here, and here.", "zh": "紧急安全出口分别位于此处、此处以及此处。", "note": "安全演示 Exits are here", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 11, "en": "In the event of decompression, place oxygen masks over your face.", "zh": "如遇机舱失压，请将氧气面罩罩在口鼻处。", "note": "飞行安全 oxygen masks", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 12, "en": "Life jackets can be found under your seat.", "zh": "救生衣放置在您的座椅下方。", "note": "救生衣 life jackets", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 13, "en": "In case of forced landing, adopt the following position.", "zh": "如遇紧急迫降，请采取以下防冲击姿势。", "note": "迫降防冲击 forced landing", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 14, "en": "Where would you like the building work to start? — In my flat.", "zh": "你想让装修工程从哪儿开工？— 在我公寓套房里。", "note": "搞错地点 start in my flat", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 15, "en": "We want you to start work in Eunice's flat: 31 Evergreen Street.", "zh": "我们希望你们直接开工砸尤妮斯的私人公寓：长青街31号。", "note": "搞出大乌龙 Eunice's flat", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 16, "en": "Do women really go for you in that uniform? — Yeah!", "zh": "女人们真的会因为这套帅气制服倒追你吗？— 那当然！", "note": "迷之自信 go for you", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 17, "en": "Currently flying at 20,000 feet, heading for Barbados!", "zh": "目前正巡航于两万英尺高空，全速飞往巴巴多斯岛！", "note": "电话吹牛 20000 feet", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 18, "en": "We're just not being attacked. It's just a bit of turbulence!", "zh": "我们没遭遇敌机空袭，只不过遇上了一点气流颠簸而已！", "note": "气流颠簸 turbulence", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 19, "en": "The builders were supposed to work at Channel 9! Your mistake: You fix it!", "zh": "装修队本应该去第9频道施工的！你的大疏忽：你自己摆平！", "note": "上司暴怒 Your mistake", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 20, "en": "Until you do, I'm going to stay in your flat!", "zh": "在你们修好之前，我就直接搬进你们家住下了！", "note": "鸠占鹊巢 stay in flat", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 21, "en": "Eunice is so angry. I made a tiny little mistake at work.", "zh": "尤妮斯肺都要气炸了，我只不过犯了个微不足道的小错。", "note": "轻描淡写 tiny mistake", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 22, "en": "You have to get a pilot's uniform: It's magic with women!", "zh": "你必须去搞一套飞行员制服：这对撩妹来说简直有魔力！", "note": "制服法宝 magic with women", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 23, "en": "I want my breakfast now! What would you like?", "zh": "我现在就要吃早餐！— 您想用点什么？", "note": "刁难要求 breakfast", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 24, "en": "You'll have to go out and buy them for me.", "zh": "所以你们现在立刻出门去给我买齐！", "note": "颐指气使 buy for me", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 25, "en": "You have to save us! Try to be calm!", "zh": "你必须拯救我们大家！— 请大家尽量保持镇静！", "note": "对戏排练 save us", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 26, "en": "You didn't have to slap me for real!", "zh": "你演戏用不着真往我脸上甩耳光吧！", "note": "假戏真做 slap for real", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 27, "en": "The actress, she's ill, but we must still do the play.", "zh": "女主演突发重病，但演出绝不能取消。", "note": "演出突发危机 actress ill", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 28, "en": "I know the perfect person to play the part: Hector!", "zh": "我知道由谁来顶替这个角色最完美不过了：赫克托！", "note": "拉人下水 perfect person", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 29, "en": "I have an extra ticket to Paris. Do you want to come with me?", "zh": "我这里多出一张去巴黎的机票。你想跟我一起去吗？", "note": "巴黎之约 ticket to Paris", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 30, "en": "You call this a breakfast? That's what I think of this!", "zh": "你管这玩意儿叫早餐？这就是我对它的评价（直接打翻）！", "note": "掀翻早餐 call this breakfast", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 31, "en": "I got some polish for Granny's chest. I love it so much.", "zh": "我买了专门保养奶奶留下的旧木箱的蜡油，我太珍爱它了。", "note": "保养古董 Granny's chest", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 32, "en": "I don't want to lose my job. It's only for a few days.", "zh": "我不想丢掉饭碗，这也就忍耐两三天而已。", "note": "委曲求全 lose my job", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 33, "en": "Why don't you stay here while we are away? — No, thank you!", "zh": "要不趁我们出门，你留在这儿陪尤妮斯？— 不了，多谢好意！", "note": "落荒而逃 while away", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 34, "en": "You are going to play the stewardess! — You are not serious!", "zh": "你来反串出演空中空姐！— 你疯了吧，别开玩笑了！", "note": "反串空姐 stewardess", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 35, "en": "Will you fly with me? — No, I am not doing it!", "zh": "你愿意做我的空姐跟我一起翱翔吗？— 不行，我死也不演！", "note": "坚决抗拒 fly with me", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 36, "en": "It is that chest! I gave it a makeover!", "zh": "那就是那个古董木箱！我把它整个重新刷漆改造了一番！", "note": "毁掉古董 gave it makeover", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 37, "en": "The hostess was beautiful: in a masculine way!", "zh": "那位‘空姐’美若天仙：带着一股浓烈的纯爷们阳刚之气！", "note": "剧评调侃 masculine way", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 38, "en": "Nick, you cannot fly this plane! — I am Captain Chip Harding, I can do anything!", "zh": "尼克，你根本不会开飞机！— 我是奇普·哈丁机长，我无所不能！", "note": "入戏太深 I can do anything", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 39, "en": "You are just an actor. Captain Chip Harding is your character!", "zh": "你不过就是个演员！奇普·哈丁只是你演的虚构角色！", "note": "当头棒喝 just an actor", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 40, "en": "But I have the heart of a pilot!", "zh": "但我体内流淌着属于真正飞行员的热血！", "note": "戏精中二 heart of a pilot", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 41, "en": "We've spoken to the builders: Your flat's ready!", "zh": "我们和施工队谈妥了：您的公寓已经装修完工了！", "note": "送走恶魔 flat's ready", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 42, "en": "What happened here? A hurricane? — Something like that.", "zh": "这屋里发生什么惨剧了？刮了龙卷风吗？— 差不多吧。", "note": "狼藉不堪 A hurricane", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 43, "en": "So, Mr. Pilot, shall we have some fun? Will you take me flying?", "zh": "那么飞行员先生，我们要不要找点乐子？你愿意带我去兜风翱翔吗？", "note": "被制服迷倒 take me flying", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 44, "en": "Shall we stay here or go to my place? — Let's go to your place!", "zh": "我们是待这儿，还是去我的公寓？— 咱们去你家吧！", "note": "成功带走 go to your place", "b64": "", "src": "extra"}, {"l": 124, "lt": "Extra E24 飞行员尼克", "i": 45, "en": "At last, she's gone! Exhausted!", "zh": "谢天谢地，那个恶魔终于走了！简直把我累垮了！", "note": "如释重负 she's gone", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 1, "en": "Damien Palasco: The most important artist of this century!", "zh": "达米安·帕拉斯科：本世纪最具分量的当代艺术大师！", "note": "当代艺术 Damien Palasco", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 2, "en": "He's so raw, so angry.", "zh": "他的作品风格是如此原始纯粹，如此充满愤怒与力量。", "note": "艺术评价 raw and angry", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 3, "en": "Anyone who is anyone will be there tomorrow night.", "zh": "明天晚上，全城所有的名流大咖通通都会亲临现场。", "note": "名流盛会 Anyone who is anyone", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 4, "en": "I'll take anyone out to dinner who gets me those tickets.", "zh": "谁要是能替我搞到那两张门票，我就请谁共进烛光晚餐。", "note": "门票诱惑 dinner", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 5, "en": "I've got fans to ignore.", "zh": "我得走了，我还有大批狂热粉丝等着我去故意冷落呢。", "note": "大牌傲慢 fans to ignore", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 6, "en": "We're seeing what it's like to be a battery chicken.", "zh": "我们正在切身体验当一只笼养肉鸡是什么滋味。", "note": "行为艺术 battery chicken", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 7, "en": "A chicken that runs on batteries? — No, a chicken kept in a small box!", "zh": "靠电池的机器鸡？— 不是！是终生被关在狭窄笼子里下蛋的鸡！", "note": "谐音幽默 battery chicken", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 8, "en": "Tomorrow there is a big farm animal freedom protest in Trafalgar Square.", "zh": "明天在特拉法加广场有一场大型关爱农场动物自由抗议集会。", "note": "环保集会 freedom protest", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 9, "en": "Boggy and Moss are very serious eco-warriors.", "zh": "博吉和莫斯是极其严肃硬核的生态环保斗士。", "note": "环保斗士 eco-warriors", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 10, "en": "They fight for the environment.", "zh": "他们毕生都在为拯救自然生态环境而奋战。", "note": "环保理念 environment", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 11, "en": "Good old Dave. He just can't resist me.", "zh": "老好人戴夫，他对我向来毫无抵抗招架之力。", "note": "自鸣得意 can't resist me", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 12, "en": "I've got two preview tickets for Damien Palasco.", "zh": "我搞到了两张达米安·帕拉斯科画展的独家预展贵宾票。", "note": "搞到贵宾票 preview tickets", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 13, "en": "How could I forget you? Meet for drinks at your place first?", "zh": "我怎么可能会忘了你呢？先去你的公寓小酌几杯如何？", "note": "热情约会 drinks at your place", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 14, "en": "It's just a simple loft-style apartment.", "zh": "我那儿不过就是间简简单单的极简工业风Loft公寓。", "note": "凡尔赛装腔 loft-style", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 15, "en": "I can tell a lot about a woman from her art.", "zh": "从一个女人钟爱的艺术品位，我能洞悉她的灵魂内心。", "note": "装腔搭讪 from her art", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 16, "en": "They call me Arty Marty, you know.", "zh": "圈内人都叫我‘艺术范儿马蒂’，懂的都懂。", "note": "艺术自封 Arty Marty", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 17, "en": "Dinner with Marty! What shall I wear?", "zh": "要和马蒂共进晚餐啦！天哪，我该穿什么才好？", "note": "盛装打扮 What shall I wear", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 18, "en": "Annie, look at this flat! I've got 24 hours!", "zh": "安妮，你看看这屋里乱成什么样了！我只有最后24小时了！", "note": "抓狂备战 24 hours", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 19, "en": "I'm feeding Hector cornflakes. Why? — He's a turkey!", "zh": "我正在给赫克托喂玉米片。— 为什么？— 因为他现在是一只火鸡！", "note": "离谱角色扮演 He's a turkey", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 20, "en": "Turkeys are made to eat lots for Christmas. It's cruel!", "zh": "火鸡在圣诞节前被迫暴饮暴食催肥，这太残忍了！", "note": "动物保护 It's cruel", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 21, "en": "He is a baby cow: A veal calf!", "zh": "他扮演的是一只刚出生的小牛犊：小牛肉小牛！", "note": "角色扮演 veal calf", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 22, "en": "You're preparing this flat because Marty Ross is coming for drinks.", "zh": "你们必须把整个公寓彻底大改造，因为马蒂·罗斯要来家里喝酒。", "note": "紧急筹备 coming for drinks", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 23, "en": "I want this flat to look like the coolest art gallery in London: The Tate Modern!", "zh": "我要把这间公寓布置成全伦敦最酷炫的现代艺术馆：泰特现代艺术馆！", "note": "艺术馆 Tate Modern", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 24, "en": "No furniture! I want 21st century! I want art!", "zh": "扔掉所有笨重家具！我要21世纪前卫先锋感！我要纯粹的艺术！", "note": "先锋艺术 I want art", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 25, "en": "I'll skip my beauty sleep. See you in the morning. Have fun!", "zh": "那我就牺牲我的美容觉成全你们吧，明早见，玩得开心！", "note": "甩手掌柜 beauty sleep", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 26, "en": "I'll give Ziggy the keys to your flat. — Okay, let's get on with it!", "zh": "你要敢偷懒，我就把你的公寓钥匙直接给齐吉。— 行行行，快动手干活！", "note": "被逼开工 get on with it", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 27, "en": "I want nibbles: Nuts, crisps!", "zh": "我要准备下酒小食：坚果、薯片通通摆上！", "note": "下酒小食 nibbles", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 28, "en": "Hector, you prepare the drinks. And Nick, try to be more interesting!", "zh": "赫克托你负责调酒，尼克，麻烦你表现得稍微有趣有深度一点！", "note": "分工吩咐 more interesting", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 29, "en": "I'll show her interesting!", "zh": "我非得好好给她瞧瞧什么才叫真正的‘有深度’！", "note": "赌气发誓 show her interesting", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 30, "en": "Ziggy fed me lots of milk.", "zh": "齐吉刚才硬灌了我好大一满桶牛奶。", "note": "搞笑扮演 fed lots of milk", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 31, "en": "Bridget made us change the flat so it looked arty.", "zh": "布里吉特逼着我们把客厅大动干戈，好让它看起来像艺术展厅。", "note": "大改造 looked arty", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 32, "en": "So, you are Annie's friends. I am Annie's boyfriend.", "zh": "这么说你们就是安妮的朋友了。我是安妮的正牌男朋友。", "note": "宣示主权 Annie's boyfriend", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 33, "en": "Would you like a drink? Coffee? Sugar?", "zh": "各位想喝点什么吗？咖啡？需要加糖吗？", "note": "招待客人 Would you like a drink", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 34, "en": "It is just that they are a bit scary.", "zh": "问题是……他们这帮生态斗士长相实在有点让人瘆得慌。", "note": "实话实说 a bit scary", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 35, "en": "Annie says you can't go to Trafalgar Square.", "zh": "安妮说你们不能去特拉法加广场了。", "note": "临时变动 Trafalgar Square", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 36, "en": "Nibbles? The nibbles! Yes, of course, Bridget.", "zh": "小零食点心？对，下酒零食！没问题布里吉特，包在我身上。", "note": "慌乱应对 nibbles", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 37, "en": "Well done, Hector. I knew I could rely on you.", "zh": "干得漂亮赫克托，我就知道你向来最靠得住了。", "note": "称赞靠谱 rely on you", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 38, "en": "This is interesting. What shall I do?", "zh": "这玩意儿可真够有深度的，我该怎么处理呢？", "note": "尼克的现代艺术 interesting", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 39, "en": "That looks much better!", "zh": "这看起来可比刚才顺眼太多了！", "note": "满意成果 much better", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 40, "en": "It tastes good. You don't even notice them now.", "zh": "味道还挺不赖的嘛，现在谁也注意不到它们了。", "note": "偷吃小吃 tastes good", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 41, "en": "And this is fantastic: Original! Very Damien Palasco!", "zh": "还有这个雕塑，简直神了：独具匠心！极具达米安·帕拉斯科的艺术神韵！", "note": "盲目吹捧 Very Damien Palasco", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 42, "en": "Is it for sale? Name your price!", "zh": "这件绝世艺术品卖不卖？随便你开价，多少钱我都收！", "note": "土豪买单 Name your price", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 43, "en": "The man's an idiot. He wants to buy it!", "zh": "这家伙纯粹是个冤大头傻帽，他居然真想买下这堆破烂！", "note": "啼笑皆非 man's an idiot", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 44, "en": "Can you deliver them to me tomorrow? — Sure, no problem!", "zh": "你们明天能负责把这件展品送到我家吗？— 没问题，包送上门！", "note": "痛快成交 deliver tomorrow", "b64": "", "src": "extra"}, {"l": 125, "lt": "Extra E25 艺术鉴赏", "i": 45, "en": "It's an Arty Marty: Rich, sickly, and very thick!", "zh": "这就是所谓的‘艺术马蒂’：浑身多金、油腻做作、而且脑子蠢得像块砖！", "note": "双关绝杀 very thick", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 1, "en": "Detective David Hunt, Metropolitan Police. Could I have a word with you, please?", "zh": "大伦敦警察厅戴维·亨特侦探。能耽误二位几句话的时间吗？", "note": "警察上门 a word with you", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 2, "en": "I'm doing a sponsored silence for the charity: Pigs with No Parents!", "zh": "我正在为慈善活动‘失依孤儿小猪’进行禁语默哀筹款！", "note": "禁语募捐 sponsored silence", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 3, "en": "I'm going to see my beautician later. — What for? — Just for a checkup!", "zh": "我待会儿要去见美容师。— 去干嘛？— 就是去做常规面容体检！", "note": "美容体检 checkup", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 4, "en": "You have a toothache? Then you must go to the dentist!", "zh": "你牙疼？那你必须立刻去看牙医！", "note": "牙疼看牙 toothache", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 5, "en": "Nick doesn't like the D-word: Dentist!", "zh": "尼克讨厌听到带D开头的那个词：Dentist（牙医）！", "note": "忌讳牙医 D-word", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 6, "en": "So when did you last see the plumber? — Five months ago? — Five years ago!", "zh": "那你上次找‘水管工（牙医）’是什么时候？— 五个月前？— 五年前！", "note": "拖延就医 five years ago", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 7, "en": "Sweets are bad for your teeth.", "zh": "糖果甜食对你的牙齿伤害可大了。", "note": "护齿常识 bad for teeth", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 8, "en": "No, he has a toothache, so he must see the plumber!", "zh": "不，他现在牙疼得要命，所以他必须去见水管工！", "note": "爆笑代号 see the plumber", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 9, "en": "He doesn't need a plumber, he needs a dentist!", "zh": "他不需要什么通水管的水管工，他需要的是正儿八经的牙医！", "note": "纠正常识 needs a dentist", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 10, "en": "We have an emergency here! What are the symptoms? Shaking, squealing!", "zh": "我们这儿有个急诊！有什么症状？浑身发抖、嗷嗷怪叫！", "note": "夸张症状 emergency", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 11, "en": "Sorted! He'll see Nick now.", "zh": "搞定办妥了！医生同意现在就给尼克看诊。", "note": "搞定预约 Sorted", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 12, "en": "Bernard, listen: You must call the police!", "zh": "伯纳德听着：你必须马上打电话报警！", "note": "劝说报警 call the police", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 13, "en": "I'm here to investigate a robbery of Bernard Reynolds.", "zh": "我是来调查伯纳德·雷诺兹先生家中失窃被盗一案的。", "note": "调查案件 investigate robbery", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 14, "en": "Who would want Bernard's clothes?", "zh": "这世上有谁会看上伯纳德那些土得掉渣的衣服啊？", "note": "嫌弃衣服 Bernard's clothes", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 15, "en": "Where were you last night?", "zh": "昨天晚上案发时你人在哪里？", "note": "审问行踪 Where were you", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 16, "en": "She can't speak: She's doing a sponsored silence for charity!", "zh": "她不能开口说话：她正在为慈善机构进行禁语募捐！", "note": "解释禁语 for charity", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 17, "en": "There was a beautiful girl and a motorbike!", "zh": "昨晚有个绝色美女，还有一辆超酷的摩托车！", "note": "手势比划 motorbike", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 18, "en": "You were with a young woman on a motorbike? Registration?", "zh": "你昨晚和一名年轻女子骑摩托车在一起？车牌号是多少？", "note": "追查线索 Registration", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 19, "en": "The young woman was on television on a motorbike!", "zh": "那个年轻女人是在电视节目里骑着摩托车！", "note": "虚惊一场 on television", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 20, "en": "He wanted to know where I was last night.", "zh": "警官想要查清楚我昨晚到底身在何处。", "note": "盘问不在场证明 last night", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 21, "en": "Hector managed to translate for me.", "zh": "好在赫克托勉强帮我充当了手语翻译。", "note": "充当翻译 translate for me", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 22, "en": "My investigations are going very well.", "zh": "我目前的案件刑侦侦查工作进展得非常顺利。", "note": "盲目自信 investigations", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 23, "en": "You need some clothes, Bernard!", "zh": "伯纳德，你身上真得裹几件衣服遮遮羞了！", "note": "没穿衣服 need clothes", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 24, "en": "And then someone stole my clothes: Bingo!", "zh": "然后紧接着就有人把我所有的衣服给洗劫一空了：太准了！", "note": "失窃抱怨 stole my clothes", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 25, "en": "I'd like to ask you a few questions.", "zh": "我想向您请教核实几个关键问题。", "note": "例行讯问 a few questions", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 26, "en": "Is there something wrong with your top lip? — It's bright red!", "zh": "你的上嘴唇出什么问题了吗？— 鲜红肿胀得像根香肠！", "note": "美容翻车 bright red", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 27, "en": "You're still very pretty.", "zh": "你看起来依然非常娇美动人。", "note": "安慰好友 still very pretty", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 28, "en": "Where were you last night? — Looking in the mirror. All night!", "zh": "你昨晚在哪儿？— 照镜子。整整照了一整夜！", "note": "奇葩证明 in mirror", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 29, "en": "How could anyone spend all night looking at themselves in the mirror?", "zh": "怎么可能会有人能在镜子前盯着自己臭美整整一个通宵？", "note": "难以置信 look in mirror", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 30, "en": "Let me summarize everybody's alibis.", "zh": "现在让我来逐一梳理一下在座各位的不在场证明。", "note": "梳理案情 summarize alibis", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 31, "en": "She would not have had time to take Bernard's clothes.", "zh": "她根本没有作案时间去盗取伯纳德的衣物。", "note": "排除嫌疑 no time to take", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 32, "en": "What's more, Bernard's clothes would be too big for her.", "zh": "况且，伯纳德那宽大的衣服套在她身上也太大了。", "note": "体型不符 too big for her", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 33, "en": "Nick was watching babes and bikes on television.", "zh": "尼克昨晚在电视前看美女与摩托车狂飙节目。", "note": "核对证明 babes and bikes", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 34, "en": "Bridget was looking at herself in a mirror all night: An unlikely story!", "zh": "布里吉特整夜都在镜子前自恋端详：荒诞不经的说辞！", "note": "不可信 unlikely story", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 35, "en": "However, if I accuse her, she'll start crying again!", "zh": "然而只要我一指控她，她肯定又得当场号啕大哭起来！", "note": "投鼠忌器 start crying", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 36, "en": "And I can't stand hysterical women!", "zh": "我这辈子最受不了的就是歇斯底里的疯女人！", "note": "侦探软肋 hysterical women", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 37, "en": "Hector is wearing a terrible suit: It looks stolen! Nobody would buy it!", "zh": "赫克托穿着一身极其老气的西装：看着就像偷来的！", "note": "毒舌西装 looks stolen", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 38, "en": "And his only alibi is Annie. And guess what? She can't speak!", "zh": "而他唯一的不在场证明人就是安妮。安妮根本说不出话！", "note": "陷入被动 She can't speak", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 39, "en": "I think that someone here is not telling the truth: And that someone is you!", "zh": "我认为在座当中有人没说实话：而那个人就是你！", "note": "锁定嫌犯 not telling truth", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 40, "en": "Why buy new clothes when you can steal somebody else's?", "zh": "既然能白白偷别人的衣服穿，又何必自己掏腰包买新的呢？", "note": "荒谬推理 steal clothes", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 41, "en": "Someone stole my clothes! — Mum's back!", "zh": "有人把我的衣服全偷光了！— 我老妈打完宾果游戏回来了！", "note": "破案转折 Mum's back", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 42, "en": "She put them in the washing machine before she went to Bingo!", "zh": "她去玩宾果之前，顺手把衣服全都塞进洗衣机里洗了！", "note": "大乌龙 washing machine", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 43, "en": "And the clothes were in the washing machine all the time!", "zh": "那些衣服从始至终一直都好好待在洗衣机筒里！", "note": "真相大白 all the time", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 44, "en": "As I suspected: That's another case solved!", "zh": "正如我早先所预料的一样：本神探又破获了一桩大案！", "note": "强行挽尊 case solved", "b64": "", "src": "extra"}, {"l": 126, "lt": "Extra E26 不在场证明", "i": 45, "en": "I'll be off then. — No, you won't! You owe me 20 pounds!", "zh": "那我这就告辞了。— 慢着别走！你还欠我们二十英镑呢！", "note": "扣下侦探 owe 20 pounds", "b64": "", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 1, "en": "I think it is quite clever.", "zh": "我觉得这挺聪明的。", "note": "口语评价：quite clever 相当机智/高明", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 2, "en": "What are Paul and Mandy doing in the living room?", "zh": "保罗和曼迪在客厅里干什么呢？", "note": "现在进行时：What are ... doing", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 3, "en": "They're kissing! — They're not kissing, they're whispering.", "zh": "他们在接吻！——他们没接吻，他们在咬耳朵说悄悄话。", "note": "口语对比：whispering 窃窃私语/低语", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 4, "en": "Mandy said they could live without kissing for 24 hours. And look, they failed!", "zh": "曼迪说他们能24小时不接吻，结果你看，他们破戒认输了！", "note": "核心句型：live without sth 没有…也能生活/戒掉…", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 5, "en": "I couldn't live without kissing Hector for 24 hours.", "zh": "让我24小时不亲赫克托，我可做不到。", "note": "情态表达：couldn't live without", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 6, "en": "Why don't you try?", "zh": "你何不试试看呢？", "note": "经典建议句型：Why don't you try?", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 7, "en": "You should stop chewing gum.", "zh": "你应该把嚼口香糖的毛病给戒了。", "note": "习惯表达：stop doing sth 停止做某事", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 8, "en": "I bet you couldn't stop chewing gum for 24 hours.", "zh": "我敢打赌你肯定坚持不了24小时不嚼口香糖。", "note": "口语打赌：I bet you couldn't ...", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 9, "en": "Yes, I could! And anyway, you suck your thumb.", "zh": "我当然可以！再说了，你还吃大拇指呢！", "note": "口语反驳：Yes, I could! / suck one's thumb", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 10, "en": "I do not! Well, only when I'm stressed.", "zh": "我才没有呢！呃……只有在压力大的时候才这样。", "note": "强调否定与让步：I do not! / only when I'm stressed", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 11, "en": "I've had an idea! We could be contestants!", "zh": "我有个好主意！我们可以去报名当参赛选手！", "note": "灵光一闪：I've had an idea! / contestant 参赛者", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 12, "en": "We could be contestants on 'Can You Live Without?'", "zh": "我们可以去参加《你能离开它吗？》这个节目！", "note": "节目介词：contestant on a TV show", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 13, "en": "It's just 24 hours of giving up our favourite things.", "zh": "这不过就是戒掉我们最喜欢的东西24小时而已。", "note": "短语：give up 放弃/戒除", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 14, "en": "It would be easy. Think of the prize money! And Marty Ross presents it.", "zh": "太轻松了！想想那笔巨额奖金吧！而且还是马蒂·罗斯主持的。", "note": "口语号召：Think of the prize money! / present 主持", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 15, "en": "He said he needed time away from me to really appreciate me. — So he dumped you then!", "zh": "他说他需要跟我分开一段时间才能真正懂我的好。——说白了他就是把你给甩了呗！", "note": "地道俚语：dump sb 甩了某人/跟某人分手", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 16, "en": "Are you feeling persuasive? — Of course, I'm always feeling persuasive.", "zh": "你觉得你能说服得了人吗？——那当然，我向来极具说服力。", "note": "地道形容词：persuasive 有说服力的/能言善辩的", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 17, "en": "Well, it's time to persuade Marty that we want to go on 'Can You Live Without?'", "zh": "好吧，该去说服马蒂让我们上《你能离开它吗？》这档节目了！", "note": "句型：it's time to do sth / persuade sb that...", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 18, "en": "Oh, I wish I could help you, but it's not my decision. It's the producers'.", "zh": "哎呀，我真想帮你，但这不是我能决定的，这得看制片人的意思。", "note": "委婉推脱：I wish I could help you, but it's not my decision.", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 19, "en": "Well, that's a shame. Because I'd hate for the newspapers to see this.", "zh": "哎，那可真是太遗憾了。因为我可不希望报社记者看到这张照片呢。", "note": "威胁兼谈判：that's a shame / I'd hate for sb to do sth", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 20, "en": "Don't you remember? I'm Eunice's researcher. I research.", "zh": "你不记得了吗？我是尤妮斯的调查员，我专搞调查挖掘底细。", "note": "职业自信：researcher / I research", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 21, "en": "I wish I could help you, but it's not my decision. It's the newspapers'!", "zh": "我也很想帮你呀，但这不是我说了算，得看各大报社怎么想咯！", "note": "经典反讽：以彼之道还施彼身", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 22, "en": "I'll see what I can do.", "zh": "我看我能怎么帮你想想办法吧。", "note": "口语高频：I'll see what I can do 我尽力而为", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 23, "en": "Guess what? I persuaded Marty Ross to get us on 'Can You Live Without?'", "zh": "猜猜怎么着？我说服马蒂·罗斯让我们上《你能离开它吗？》了！", "note": "惊喜开场：Guess what? / get us on 让我们上节目", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 24, "en": "If we can live without our favourite things, we'll win a super holiday!", "zh": "只要我们能戒掉自己最喜欢的东西，我们就能赢取豪华度假大奖！", "note": "条件从句：live without our favourite things", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 25, "en": "It's just 24 hours of giving up our favourite things. It will be easy for me!", "zh": "只要忍耐24小时不碰心爱之物就行。对我来说简直易如反掌！", "note": "自信满满：easy for me", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 26, "en": "Darlings, do you want to spend the next 24 hours with me?", "zh": "亲爱的观众朋友们，你们想和我共度接下来的24小时吗？", "note": "节目主持开场白：spend the next 24 hours with me", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 27, "en": "What's your name? — You already know my name, Marty.", "zh": "你叫什么名字？——马蒂，你明明早就知道我的名字。", "note": "老相识过招：You already know my name.", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 28, "en": "Don't get smart, sweetie. This is my show, photo or no photo!", "zh": "别耍小聪明，亲爱的。不管有没有照片把柄，这可是我的地盘！", "note": "口语警告：Don't get smart 别耍小聪明 / photo or no photo", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 29, "en": "My name is Annie and I'm Hector's girlfriend. And I love Charlie, my dog.", "zh": "我叫安妮，我是赫克托的女朋友。而且我最爱我的狗狗查理。", "note": "自我介绍：girlfriend / dog", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 30, "en": "So which one could you live without?", "zh": "那么这两个你更舍得离开哪一个呢？", "note": "尖锐提问：which one could you live without?", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 31, "en": "Annie loves her dog more than you!", "zh": "安妮爱她的狗胜过爱你！", "note": "扎心对比：love ... more than ...", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 32, "en": "This is Nick and he likes babes.", "zh": "这位是尼克，他的最爱是美女辣妹。", "note": "诙谐介绍：babes 辣妹/美女", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 33, "en": "As usual, each of these contestants has picked one thing that their flatmates cannot live without for 24 hours.", "zh": "照例，每位选手都选出了一样室友们24小时内绝对离不开的心头好。", "note": "长句听力：as usual / flatmates 室友", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 34, "en": "Bridget, you must live without chocolate, mirrors and makeup.", "zh": "布里奇特，你必须做到不碰巧克力、不照镜子，而且不化妆。", "note": "规则宣布：live without chocolate, mirrors and makeup", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 35, "en": "Annie, you must live without touching Hector, sucking your thumb, and Charlie.", "zh": "安妮，你必须做到不碰赫克托、不吸大拇指，更不能见查理。", "note": "动名词列举：touching Hector, sucking thumb", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 36, "en": "Hector, you must live without touching Annie and chewing gum.", "zh": "赫克托，你必须做到不碰安妮，而且不嚼口香糖。", "note": "禁令：live without touching Annie and chewing gum", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 37, "en": "Nick, you must live without talking about babes or talking about motorbikes.", "zh": "尼克，你必须做到不准谈论美女，也不准谈论摩托车。", "note": "言语禁令：without talking about babes or motorbikes", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 38, "en": "And all of you must live without television, magazines and music.", "zh": "而且你们所有人都不准看电视、不准翻杂志、不准听音乐。", "note": "全面戒断：without TV, magazines and music", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 39, "en": "24 hours of living without starts now!", "zh": "24小时极限戒瘾挑战，现在正式开始！", "note": "倒计时启动：starts now", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 40, "en": "Don't forget I'll be watching! If you touch, we lose points.", "zh": "别忘了我一直在盯着你们！只要碰一下，我们就会被扣分。", "note": "警告句：I'll be watching / lose points 扣分", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 41, "en": "Top points could mean a holiday in the Caribbean, but if they fail, they lose points.", "zh": "拿到最高积分就能去加勒比海度假，但如果失败了，就会扣光积分。", "note": "奖惩规则：holiday in the Caribbean / fail 失败", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 42, "en": "That doesn't stop me dreaming about them though.", "zh": "不过这可阻止不了我在梦里想她们。", "note": "口语机智转折：That doesn't stop me doing sth though.", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 43, "en": "I think it's going to rain. — Do you? — I agree.", "zh": "我觉得要下雨了。——是吗？——我也觉得。", "note": "尬聊日常：天气话题与应答 I agree", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 44, "en": "Manchester United are doing well. — Are they? — I agree.", "zh": "曼联队最近踢得挺好啊。——是吗？——我也觉得。", "note": "英式寒暄：谈论足球 Manchester United", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 127, "lt": "Extra E27 戒瘾考验", "i": 45, "en": "Come on, Annie. We have lots of catching up to do!", "zh": "快来吧安妮，咱们俩可得好好把没亲够的给补回来！", "note": "地道习语：have lots of catching up to do 很多旧要叙/弥补", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 1, "en": "I'm going to show you what a traditional English Christmas is like.", "zh": "我要带你体验一下地道的传统英式圣诞节是什么样的。", "note": "文化介绍：traditional English Christmas", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 2, "en": "It's an English tradition: When you stand under it, you can kiss someone.", "zh": "这是英国的传统习俗：只要站在槲寄生下面，你就可以吻别人了。", "note": "英国习俗：mistletoe 槲寄生", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 3, "en": "I am not under any mistletoe. — You are now!", "zh": "我才没有站在槲寄生下面呢。——现在你站在下面了！", "note": "甜蜜互动：You are now!", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 4, "en": "Not a party, three more parties! And that's just tonight!", "zh": "不是一场派对，是还有三场派对！而且光是今晚就有三场！", "note": "数量强调：three more parties / just tonight", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 5, "en": "You've been to a Christmas party every night for two weeks! — And it's so difficult being so popular!", "zh": "你这两个星期以来每晚都去赶圣诞派对！——哎呀，人太受欢迎就是这么辛苦！", "note": "自恋幽默：difficult being so popular", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 6, "en": "First there's a champagne party at the Savoy, then at 9 o'clock I'll get a taxi to the Ritz and get changed on the way.", "zh": "先是去萨伏伊酒店参加香槟派对，然后9点我打车去丽兹酒店并在路上换好衣服。", "note": "伦敦名所：the Savoy / the Ritz / get changed on the way", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 7, "en": "What? In the taxi? — Naturally!", "zh": "什么？在出租车里换？——那当然了！", "note": "高频回应：Naturally! 理所当然/自然是这样", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 8, "en": "And then at 11 o'clock I'll get a taxi to Annabel's. — Annabel, who is she?", "zh": "然后11点我会打车去安娜贝尔。——安娜贝尔是谁呀？", "note": "误会幽默：误把夜店名字当成人名", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 9, "en": "Annabel's is a nightclub! — Will you change your clothes in the taxi again?", "zh": "安娜贝尔是一家高级夜总会！——你还要在出租车里再换一次衣服吗？", "note": "夜生活词汇：nightclub 夜总会", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 10, "en": "And there I hope I will meet a young handsome man: An early Christmas present!", "zh": "在那儿我希望偶遇一位英俊潇洒的帅哥：当作我提前收到的圣诞礼物！", "note": "风趣表达：an early Christmas present", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 11, "en": "Is the money good? — Stop complaining then!", "zh": "工资给得高吗？——那你就别抱怨了呗！", "note": "口语劝诫：Stop complaining then!", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 12, "en": "Hector and I are going to have a lovely Christmas. Christmas is all about parties and presents.", "zh": "我和赫克托会度过一个温馨甜蜜的圣诞节。圣诞节的真谛就是派对和礼物。", "note": "节日核心句：all about parties and presents", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 13, "en": "So, Bridget, have you got your Christmas stocking ready?", "zh": "那么布里奇特，你的圣诞长袜准备好了吗？", "note": "传统物品：Christmas stocking 圣诞袜", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 14, "en": "What is a Christmas stocking?", "zh": "圣诞长袜是用来干什么的？", "note": "疑问句：What is a Christmas stocking?", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 15, "en": "On Christmas Eve you hang up your Christmas stocking and Father Christmas comes and fills it up!", "zh": "在平安夜你把圣诞袜挂起来，慈祥的圣诞老人就会来把它装得满满当当！", "note": "英式英语：Father Christmas (英) = Santa Claus (美)", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 16, "en": "So, what else do you have at Christmas? — Turkey, Christmas pudding, mince pies.", "zh": "那圣诞节还要吃些什么呢？——火鸡、圣诞布丁，还有百果馅饼。", "note": "经典圣诞美食：Turkey, Christmas pudding, mince pies", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 17, "en": "How do you make them? — It's just pastry and mincemeat.", "zh": "这个怎么做呢？——就是酥皮裹上干果馅料。", "note": "烘焙词汇：pastry 酥皮点心面团 / mincemeat", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 18, "en": "It's traditional: It's sultanas, raisins and spices.", "zh": "这是传统配方：里面有无籽白葡萄干、普通葡萄干和各种香料。", "note": "传统原料：sultanas, raisins and spices", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 19, "en": "What do you get if you cross a chicken with a clock? — An alarm cluck!", "zh": "如果把母鸡和钟表杂交在一起会得到什么？——一个咯咯叫的闹钟！", "note": "圣诞饼干冷笑话：alarm clock 与 cluck(母鸡叫声) 谐音", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 20, "en": "It's an English tradition: When you stand under it, you can kiss someone.", "zh": "这是英国传统：当你站在槲寄生下，就可以亲吻身边的人。", "note": "复习重现：kiss under mistletoe", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 21, "en": "I had so many exciting parties to go to: It's so difficult being so popular!", "zh": "我有那么多精彩的派对要赶场：人气太高真的好心累！", "note": "布里奇特金句：so difficult being so popular", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 22, "en": "Hector, you are clever! — I followed the recipe.", "zh": "赫克托，你真能干！——我是严格照着菜谱做的。", "note": "烹饪高频：follow the recipe 按照食谱做", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 23, "en": "No, no, no, recipe! — Recipe!", "zh": "不对不对，发音是 recipe（菜谱）！——菜谱！", "note": "易错发音精讲：recipe /ˈresəpi/", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 24, "en": "Merry Christmas! Is something wrong?", "zh": "圣诞快乐！怎么了，是有什么不对劲吗？", "note": "关切询问：Is something wrong?", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 25, "en": "Christmas is all about sharing.", "zh": "圣诞节的精髓就在于与大家分享。", "note": "节日价值：all about sharing", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 26, "en": "What happened to your beard? — One Christmas candle, one small child.", "zh": "你的圣诞胡子怎么烧秃了？——一支圣诞蜡烛，外加一个熊孩子。", "note": "黑色幽默：Christmas candle / small child", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 27, "en": "Mince pies with the best meat from the best butcher!", "zh": "馅饼里放了从最好的肉铺买来的顶级鲜肉馅！", "note": "肉铺：butcher / minced meat", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 28, "en": "What did you put in the pies? — Minced meat from the best butcher!", "zh": "你在馅饼里到底放了什么？——从顶级肉铺买的鲜绞肉啊！", "note": "经典误会：mincemeat (干果馅) vs minced meat (碎绞肉)", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 29, "en": "It's mincemeat, not minced meat! — Isn't it the same thing?", "zh": "那是果脯碎，不是碎肉末！——难道这两个不是同一个东西吗？", "note": "反问求证：Isn't it the same thing?", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 30, "en": "Christmas songs: You knock on people's doors and sing to them for money!", "zh": "唱圣歌：挨家挨户敲开门，唱歌给他们听来募集善款！", "note": "颂歌习俗：carol singing 唱圣诞颂歌", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 31, "en": "Let's do it for charity: Some children have no Christmas.", "zh": "我们为慈善事业去唱颂歌吧：有些贫困孩子根本过不上圣诞节。", "note": "慈善：for charity / have no Christmas", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 32, "en": "Your job as Santa Claus is so important: You help children to believe in Christmas.", "zh": "你扮演圣诞老人这份工作无比神圣：你在守护孩子们对圣诞的纯真信仰。", "note": "鼓励治愈：believe in Christmas", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 33, "en": "You're right, Annie: My job is important. I help children to believe.", "zh": "你说得对，安妮：我的工作很重要，我帮孩子们坚守美好信念。", "note": "肯定认同：You're right", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 34, "en": "And that will make you happy. Here, have a mince pie!", "zh": "这会让你开心起来的。来，吃一个百果馅饼吧！", "note": "热情款待：Here, have a ...", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 35, "en": "I like the tree. It's nearly finished.", "zh": "我很喜欢这棵圣诞树，装饰得差不多快完工了。", "note": "完成度：nearly finished 快完成了", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 36, "en": "How was your last day as Santa Claus? — Great, such nice children!", "zh": "你当圣诞老人的最后一天过得如何？——棒极了，孩子们都太可爱了！", "note": "口语询问：How was your day?", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 37, "en": "And I've just finished my Christmas shopping! — The shops are shut now! — The petrol station was open.", "zh": "而且我刚刚把圣诞礼物都采购齐了！——商店早就关门了！——加油站的小超市还开着呢。", "note": "生活真实幽默：petrol station 加油站便利店", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 38, "en": "Mum doesn't live in Oxford! — I know, she might go there one day though.", "zh": "妈妈又不住在牛津！——我知道，不过她保不准哪天会去那儿玩呢。", "note": "无厘头借口：she might go there one day though", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 39, "en": "I bought shampoo for my sister, and aftershave for my dad.", "zh": "我给我妹妹买了洗发水，给我爸爸买了须后水。", "note": "日常护理礼品：shampoo 洗发水 / aftershave 须后水", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 40, "en": "Cheer up, Bridget! Tomorrow is Christmas Day.", "zh": "振作起来，布里奇特！明天就是圣诞节正日了。", "note": "暖心打气：Cheer up! / Christmas Day", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 41, "en": "Tomorrow is Christmas Day, and Bernard is coming for lunch. What fun!", "zh": "明天是圣诞节，伯纳德还要过来吃午餐。真让人期待！", "note": "反讽幽默：What fun! 真是“太有意思了”", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 42, "en": "I'm here for dinner. — It's a bit early! Ten o'clock! — Time for sherry!", "zh": "我是来吃大餐的。——这也来得太早了吧，才上午10点！——正合适喝雪莉酒！", "note": "英式圣诞佐餐：sherry 雪莉酒", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 43, "en": "Thank you, Hector. You shouldn't have!", "zh": "谢谢你，赫克托。你其实用不着这么破费客气的！", "note": "收礼客套金句：You shouldn't have! 哎呀你太客气了", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 44, "en": "Never mind, there is always next year. I must dash to a top restaurant for lunch.", "zh": "没关系，年年都有圣诞嘛。我得赶紧奔赴顶级餐厅吃午餐了。", "note": "地道口语：must dash 急着要走 / 赶时间", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 128, "lt": "Extra E28 圣诞快乐", "i": 45, "en": "I have another surprise for you, another English Christmas tradition: Chocolate log! One slice or two?", "zh": "我还有一个惊喜给你们，另一项英国圣诞传统：树干蛋糕！切一片还是两片？", "note": "传统甜品：Chocolate log (Yule log) 巧克力树干蛋糕", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 1, "en": "I'm going to join the SAS.", "zh": "我打算加入英国特种空勤团（SAS）。", "note": "英国特种部队：SAS (Special Air Service)", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 2, "en": "Welcome to the National Camping Exhibition!", "zh": "欢迎来到全国野营露营博览会！", "note": "展会表达：National Camping Exhibition", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 3, "en": "We will be showing you the best and the worst of camping, so stick around!", "zh": "我们将为您展现露营最好和最糟的方方面面，千万别走开！", "note": "电视主持口播：stick around 别走开/继续锁定", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 4, "en": "Shall we go and try out some sleeping bags now, Hector?", "zh": "赫克托，咱们现在去挑几个睡袋试躺一下好不好？", "note": "暧昧邀约：try out 试用/体验 / sleeping bags 睡袋", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 5, "en": "Calm down, Annie, it's only a television report.", "zh": "安妮冷静点，那不过就是一个电视新闻报道而已。", "note": "安慰劝解：Calm down / only a report", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 6, "en": "He's been with Eunice a lot recently, and I'm just worried that he, that she, you know...", "zh": "他最近老是跟尤尼斯泡在一起，我就是担心他，担心她，你懂的……", "note": "吃醋心理描写：worried that... / you know", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 7, "en": "Annie, don't be silly! You've got nothing to worry about.", "zh": "安妮，别傻了！你根本没什么好担心的。", "note": "闺蜜宽慰：You've got nothing to worry about.", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 8, "en": "Hector is a good-looking man, and she's a good-looking woman.", "zh": "赫克托是个英俊帅哥，而她也是个漂亮女人啊。", "note": "外貌评价：good-looking man/woman", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 9, "en": "Nick is training to be in the Special Air Service: 'I'm going to join the SAS!'", "zh": "尼克正在训练自己加入特种空勤团：“我要加入特种部队！”", "note": "热血幻想：training to be in...", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 10, "en": "He thinks it's the same as being a Scout!", "zh": "他以为特种兵就跟当童子军是一回事呢！", "note": "童子军：Scout 童军队员", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 11, "en": "Hector has been working a lot with Eunice recently: 'Shall we go and try out some sleeping bags now?'", "zh": "赫克托最近一直跟尤尼斯搭档工作：“咱们去睡袋里试试躺躺吧？”", "note": "复述日记：work a lot with sb recently", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 12, "en": "And he came home at 1:15 in the morning: 'Where have you been?'", "zh": "而且他凌晨1点15分才回家：“你到底去哪儿了？”", "note": "查岗质问：Where have you been?", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 13, "en": "'A few beers with the lads,' he said.", "zh": "“就是跟几个哥们儿喝了点啤酒而已，”他辩解道。", "note": "英式俚语：the lads 兄弟们/哥们儿", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 14, "en": "I could smell Eunice's perfume on him: Since when do lads start wearing ladies' perfume?", "zh": "我都能闻出他身上有尤尼斯的香水味：哥们儿什么时候开始喷女式香水了？", "note": "犀利反问：Since when do ... start wearing ladies' perfume?", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 15, "en": "What do you think of Eunice?", "zh": "你觉得尤尼斯这人怎么样？", "note": "口语询问看法：What do you think of ...?", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 16, "en": "She isn't an English rose. — I don't think she is a flower.", "zh": "她可不是一朵“英伦玫瑰”。——我也不觉得她算什么花朵。", "note": "文化比喻：English rose 英格兰端庄佳人", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 17, "en": "It's a saying: An English rose is a sweet, pretty girl, like Annie.", "zh": "这是一种俗语说法：“英伦玫瑰”指的是甜美乖巧的姑娘，就像安妮那样。", "note": "习语解释：It's a saying / sweet, pretty girl", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 18, "en": "Eunice is not a sweet, pretty girl: Eunice is more...", "zh": "尤尼斯绝不是温柔文静的小女生，尤尼斯更像是……", "note": "欲言又止：more like...", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 19, "en": "What is that plant that grows all over walls in England?", "zh": "在英国爬满整面墙的那种植物叫什么来着？", "note": "生活求助：plant that grows all over walls", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 20, "en": "Eunice is more like English Ivy! — What do you mean?", "zh": "尤尼斯更像是常春藤！——你这是什么意思？", "note": "植物隐喻：English Ivy 常春藤（缠人）", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 21, "en": "She's all over you! Do you like it?", "zh": "她整个人都缠着你、倒贴在你身上！你很享受这样吗？", "note": "地道俚语：be all over sb 缠着某人/贴在某人身上", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 22, "en": "I see trouble ahead.", "zh": "我预感到前方要有大麻烦了。", "note": "口语神预判：I see trouble ahead 我看要坏事", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 23, "en": "He was out with Eunice! — Oh, don't worry about Eunice, she likes flirting, that's all.", "zh": "他昨晚是跟尤尼斯出去的！——害，别太介意尤尼斯，她就是爱到处调情罢了。", "note": "性格描述：flirting 调情/撩人 / that's all 仅此而已", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 24, "en": "Hey, this will cheer you up! Look what I found.", "zh": "嘿，这个肯定能让你开心起来！看我找到了什么宝贝。", "note": "安慰神器：this will cheer you up", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 25, "en": "Remember the Brownie Law, Annie?", "zh": "还记得当年的小女童军誓词吗，安妮？", "note": "童军规则：Brownie Law 幼女童军守则", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 26, "en": "It is the Brownie salute! — That's not a salute, this is a salute!", "zh": "这是女童军敬礼！——那根本不算敬礼，这才叫标准军礼！", "note": "动作词汇：salute 敬礼/军礼", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 27, "en": "What do you think, Hector? — Well, both salutes are nice.", "zh": "赫克托你觉得呢？——呃，两个人的敬礼都挺好看的。", "note": "求生欲发言：both ... are nice", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 28, "en": "What are you talking about? What are Brownies? Biscuits?", "zh": "你们到底在聊什么呀？Brownies是什么？布朗尼巧克力饼干吗？", "note": "谐音幽默：Brownies (幼女童军 vs 布朗尼蛋糕)", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 29, "en": "When Bridget and I were little girls, we were Brownies: We went camping, we sang songs, and we were given badges for good work.", "zh": "我和布里奇特小时候都是女童军：我们去露营、唱歌，表现好还会发徽章。", "note": "童年回忆：Brownies / camping / badges 徽章", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 30, "en": "Brownies are for girls! In the Scouts, we survived: It was just like being in the SAS!", "zh": "女童军都是小女生的把戏！我们男童军那才叫野外求生：简直跟特种部队一模一样！", "note": "男孩吹牛：In the Scouts, we survived", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 31, "en": "So what are all those badges for? — This one is for first aid.", "zh": "那这些徽章都是奖励什么的？——这一枚是急救技能勋章。", "note": "技能词汇：first aid 急救", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 32, "en": "And where is second aid? Or third aid?", "zh": "那“二级救援”在哪呢？或者“三级救援”呢？", "note": "赫克托冷幽默：literal translation", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 33, "en": "First aid is for helping people who are hurt.", "zh": "急救是用来帮助那些受伤的人的。", "note": "概念解释：helping people who are hurt", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 34, "en": "It's called the kiss of life. — Sounds good!", "zh": "这叫作人工呼吸（生命之吻）。——听起来真不错！", "note": "急救用语：the kiss of life 人工呼吸", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 35, "en": "It means I breathe into your mouth.", "zh": "意思是把气直接吹进你的嘴里。", "note": "动作解释：breathe into your mouth", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 36, "en": "When I was in the Scouts, I went camping! — So did we! — Ah, but this was proper camping: Survival!", "zh": "我在童军的时候我也去露营过！——我们也去过啊！——哈，我那才是货真价实的露营：荒野求生！", "note": "辩论用语：proper camping 真正的露营 / Survival", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 37, "en": "We had to live off the land!", "zh": "我们当时必须靠山吃山靠水吃水，在野外自给自足！", "note": "荒野求生习语：live off the land 靠自然资源维生", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 38, "en": "Could you do a survival test? — Yeah, no problem!", "zh": "你能经受住生存大考验吗？——那当然，小菜一碟！", "note": "自信应答：survival test / no problem", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 39, "en": "We'll give you a survival test. Just be prepared!", "zh": "我们要给你们俩来一场野外生存测试，做好心理准备吧！", "note": "童军座右铭：Be prepared! 时刻准备着", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 40, "en": "Hector, get us a tent from the National Camping Exhibition.", "zh": "赫克托，从野营博览会上给我们买一顶帐篷回来吧。", "note": "野营装备：tent 帐篷", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 41, "en": "We'll see who the real men are! In the jungle, it is going to be different.", "zh": "咱们走着瞧，看看谁才是纯爷们！到了真正的丛林里，情况可就不一样了。", "note": "豪言壮语：who the real men are / In the jungle", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 42, "en": "It's three o'clock in the morning! Where have you been?", "zh": "现在都凌晨三点钟了！你到底野到哪儿去了？", "note": "深更半夜：three o'clock in the morning", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 43, "en": "Oh, a couple of beers, and a dance. — What's that on your collar?", "zh": "噢，就喝了两杯啤酒，跳了支舞。——你衣领上沾的是什么东西？", "note": "抓包现场：collar 衣领 / a couple of beers", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 44, "en": "Have you been dancing with Eunice? — Yes. — You are dead!", "zh": "你是不是跟尤尼斯跳舞了？——是的。——你死定了！", "note": "口语完蛋了：You are dead!", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 129, "lt": "Extra E29 野外露营", "i": 45, "en": "When Annie sees that I bought the tent, she is going to forgive me.", "zh": "只要安妮看到我真把帐篷买回来了，她一定会原谅我的。", "note": "心存侥幸：she is going to forgive me", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 1, "en": "Hector and Annie were in love, but now things are not so good.", "zh": "赫克托和安妮曾经深爱着彼此，但现在两人的关系却亮起了红灯。", "note": "转折叙述：things are not so good", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 2, "en": "Can I pass the sugar, coffee, tea? Actually, I was going to say we should talk.", "zh": "需要我帮你递糖、咖啡还是茶吗？其实，我是想说咱们该好好谈谈了。", "note": "破冰搭话：we should talk 我们该谈谈了", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 3, "en": "So now you want to talk to me! It's only been a week.", "zh": "哟，现在你倒想跟我说话啦！这冷战不过才过了一个星期而已嘛。", "note": "冷嘲热讽：It's only been a week.", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 4, "en": "I didn't go out with Eunice! — You did, and you stayed out until three o'clock!", "zh": "我真没跟尤尼斯约会！——你就有！而且你在外面一直鬼混到凌晨三点！", "note": "委屈辩解与质问：stay out 彻夜不归/在外面呆到很晚", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 5, "en": "There were other people there too, people who work on the program.", "zh": "当时还有其他同事在场呢，都是电视台节目组的工作人员。", "note": "澄清事实：people who work on the program", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 6, "en": "You mean other women who work on the program? I knew it!", "zh": "你的意思是节目组里其他女性工作人员吧？我就知道！", "note": "醋意满满：I knew it! 我早就猜到了", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 7, "en": "There is no other woman!", "zh": "根本就没有什么别的女人！", "note": "坚决自证：no other woman", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 8, "en": "So was that her? Debbie, the other woman?", "zh": "刚才电话里那个是她吗？黛比，那个第三者？", "note": "第三者表达：the other woman", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 9, "en": "That was Debbie from the makeup department, confirming my call time for tomorrow.", "zh": "那是化妆组的黛比，打电话跟我确认明天的通告到达时间。", "note": "电视行话：call time (演员/主播的)开工到场时间", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 10, "en": "When Eunice gets angry, she is a very scary lady.", "zh": "尤尼斯一旦发飙起来，那可真是一个极度吓人的女人。", "note": "性格描述：scary lady 可怕的女人", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 11, "en": "Prince William wants to marry you? — No, I've got a promotion!", "zh": "威廉王子要向你求婚了吗？——不是，我升职了！", "note": "职场喜讯：get a promotion 获得晋升", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 12, "en": "Editor of Channel 9 Live! Eunice is no longer my boss!", "zh": "9频道直播总监！尤尼斯再也不是我的顶头上司了！", "note": "扬眉吐气：no longer my boss", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 13, "en": "Eunice is so jealous. Now that is good news!", "zh": "尤尼斯嫉妒得眼都红了。这简直是天大的好消息！", "note": "口语赞叹：Now that is good news!", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 14, "en": "Are you cutting up photos of you and Hector? — Because Hector is no longer my boyfriend.", "zh": "你在剪碎你和赫克托的合照吗？——因为赫克托已经不再是我男朋友了。", "note": "分手仪式：cutting up photos / no longer my boyfriend", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 15, "en": "Because he is having an affair!", "zh": "因为他在外面搞外遇出轨了！", "note": "情感危机：have an affair 搞婚外情/有外遇/出轨", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 16, "en": "I think it's Debbie. And I just heard him on the phone to Lola.", "zh": "我觉得是黛比，而且我刚才还亲耳听到他在电话里跟罗拉调情。", "note": "抓现行：on the phone to sb", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 17, "en": "Lola? Who is she?", "zh": "罗拉？她又是何方神圣？", "note": "疑问句：Who is she?", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 18, "en": "What are you doing? — I am not doing, I am being.", "zh": "你在干什么呢？——我不是在干什么，我是在“成为/体验存在”。", "note": "戏精台词：I am being (体验派表演)", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 19, "en": "What are you being? Let me guess: A sumo wrestler?", "zh": "你在演什么呢？让我猜猜：相扑运动员？", "note": "幽默猜测：sumo wrestler 相扑手", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 20, "en": "I am an egg. — Of course you are an egg.", "zh": "我是一颗蛋。——那当然了，你可真像个笨蛋。", "note": "无厘头双关幽默：egg 鸡蛋/笨蛋", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 21, "en": "What sort of egg am I? Hard-boiled? Scrambled? Fried?", "zh": "我是哪种蛋？全熟水煮蛋？炒鸡蛋？还是荷包煎蛋？", "note": "各种蛋的英文：hard-boiled / scrambled / fried", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 22, "en": "You are a poached egg.", "zh": "你是一个水波蛋（溏心水波荷包蛋）。", "note": "西餐蛋类：poached egg 水波蛋", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 23, "en": "Why are you being a poached egg? — It's my new acting class!", "zh": "你干嘛要扮演水波蛋啊？——这是我新报的表演进修班的作业！", "note": "演艺志向：acting class 表演课", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 24, "en": "What are you next week? A piece of wood? Then it would be wooden acting!", "zh": "下周你要演什么？一根木头吗？那可真是名副其实的“木头般呆板演技”了！", "note": "地道双关：wooden acting 呆板生硬的演技", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 25, "en": "What do you want to talk about? — It is Annie. She thinks I'm having an affair.", "zh": "你想聊些什么？——是安妮的事。她一口咬定我在外面有了外遇。", "note": "兄弟倾诉：She thinks I'm having an affair.", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 26, "en": "Two women? You cheeky thing! — But I am not!", "zh": "脚踩两条船？你小子行啊真有本事！——可我真没有啊！", "note": "英式口语：You cheeky thing! 你个厚脸皮的小子", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 27, "en": "So tell Annie that! — I have, but she doesn't believe me.", "zh": "那你去跟安妮解释清楚啊！——我解释过了，可她根本不信我的话。", "note": "无可奈何：she doesn't believe me", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 28, "en": "Excuse me, I'll take this outside.", "zh": "不好意思，我到门外去接一下这个电话。", "note": "礼貌避嫌：take this outside 到外面接听", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 29, "en": "It's not Eunice, it's not Debbie... could it be Lola?", "zh": "不是尤尼斯，也不是黛比……难道真的是罗拉？", "note": "悬念推测：could it be...?", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 30, "en": "Why are you so angry? — I'm not, I'm just doing Zeus!", "zh": "你火气怎么这么大？——我没生气，我只是在扮演雷神宙斯！", "note": "希腊神话：Zeus 宙斯", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 31, "en": "He won't speak, he won't move! — He is being a poached egg for his new acting class.", "zh": "他不说话也不动弹！——他在为他的新表演课扮演一个水波蛋呢。", "note": "生活喜感：won't speak, won't move", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 32, "en": "Do I look like a potato? — Yes, couch potato!", "zh": "我看起来像土豆吗？——没错，像个整天瘫在沙发上看电视的懒汉！", "note": "经典熟语：couch potato 电视迷/久坐不动的人", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 33, "en": "I am not a fish, I am pain!", "zh": "我演的不是死鱼，我演的是“痛苦”！", "note": "抽象戏剧表演：I am pain", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 34, "en": "You are a pain. — Yes, Nick is a pain.", "zh": "你确实挺让人痛苦头疼的。——对，尼克真是个讨厌鬼。", "note": "常用双关俚语：a pain (in the neck) 令人讨厌的人", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 35, "en": "How was your first day as editor? — What a day! I had a very important meeting.", "zh": "你当主编总监的第一天过得怎么样？——忙死人的一天！我开了一个极其重要的高层会议。", "note": "口语感叹：What a day! 真是难忘/充实的一天", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 36, "en": "Oh, Annie, I hate it when we argue. — So do I. I miss you.", "zh": "哦安妮，我真讨厌咱们俩吵架赌气。——我也是，我好想你。", "note": "真情流露：I hate it when we argue / So do I / I miss you", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 37, "en": "Two can play that game!", "zh": "既然你这么玩，那我也奉陪到底！（你会玩这一套，我也会！）", "note": "高频习语：Two can play that game 以其人之道还治其人之身", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 38, "en": "I am long-sighted: I need to wear glasses for reading. — They suit you.", "zh": "我是远视眼：看书阅读必须戴眼镜。——眼镜挺适合你的。", "note": "眼科与夸赞：long-sighted 远视 / They suit you 很配你", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 39, "en": "Bridget, what's the matter? — I can't do it! Eunice hates me, they all hate me!", "zh": "布里奇特你怎么了？——我干不来这活！尤尼斯讨厌我，所有人全都讨厌我！", "note": "职场崩溃时刻：what's the matter / I can't do it", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 40, "en": "Bridget, you are one of the cleverest, most beautiful women I know.", "zh": "布里奇特，你是我所认识的最聪慧、最有魅力的女性之一。", "note": "高级走心鼓励：one of the cleverest, most beautiful women", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 41, "en": "Bridget, you can do this job: Channel 9 needs you!", "zh": "布里奇特，你绝对胜任得了这份工作：9频道离不开你！", "note": "全力支持：you can do this job / Channel 9 needs you", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 42, "en": "You really look handsome in those glasses.", "zh": "你戴着这副眼镜看起来真的很帅气呢。", "note": "心动夸赞：look handsome in those glasses", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 43, "en": "Hector, you look smart. — Yes, I am going to meet someone.", "zh": "赫克托，你穿得好体面精神啊。——是的，我要去见一位重要人物。", "note": "英式英汉：smart 衣冠楚楚/精明干练", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 44, "en": "Annie, Lola is a 60-year-old chief executive for ATV: Argentinian Television!", "zh": "安妮，罗拉是阿根廷国家电视台（ATV）一位60岁的女性最高执行总裁！", "note": "真相大白：chief executive 首席执行总裁", "b64": "data:audio/mp3;base64,", "src": "extra"}, {"l": 130, "lt": "Extra E30 爱情的代价", "i": 45, "en": "She wants me to return to Argentina to present their number one show. But I don't want to go: I want to stay here with you!", "zh": "她希望我回阿根廷去主持他们的王牌王牌栏目。但我不想回去：我想留在这里，跟你在一起！", "note": "大结局深情告白：I want to stay here with you!", "b64": "data:audio/mp3;base64,", "src": "extra"}];
